/*
<MODULE_CONTRACT>
<purpose>Provides a revision-by-path lookup helper that wraps the integrity registry with a git-history fallback, for consumers like the Compass audit system (RFC-0352).</purpose>
<non-goals>
  <item>Do not compute a new per-file counter — reuse the existing integrity revision.</item>
  <item>Do not modify the registry or write any files.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>RFC-0352: initial implementation of getRevisionByPath helper.</item>
</CHANGE_SUMMARY>
*/

import { loadEntitiesById, loadPathsCurrent } from "./registry.ts";
import { getFileRevisionFromHistory } from "./git.ts";
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";

export interface RevisionByPathResult {
  revision: number;
  entityId: string | null;
  contentHash: string;
}

export async function getRevisionByPath(
  cwd: string,
  repoPath: string,
): Promise<RevisionByPathResult> {
  const paths = await loadPathsCurrent(cwd);
  const entityId = paths[repoPath];

  if (entityId) {
    const entities = await loadEntitiesById(cwd);
    const entity = entities[entityId];
    if (entity) {
      let contentHash = entity.contentHash;
      // Compute live hash if the file exists
      try {
        const abs = resolve(cwd, repoPath);
        const content = await readFile(abs, "utf8");
        contentHash = "sha256-" + createHash("sha256").update(content).digest("hex");
      } catch {
        // keep registry hash
      }
      return {
        revision: entity.revision,
        entityId,
        contentHash,
      };
    }
  }

  // Fallback: compute revision from git history
  const revision = await getFileRevisionFromHistory(cwd, repoPath);
  let contentHash = "";
  try {
    const abs = resolve(cwd, repoPath);
    const content = await readFile(abs, "utf8");
    contentHash = "sha256-" + createHash("sha256").update(content).digest("hex");
  } catch {
    // file may not exist
  }

  return { revision, entityId: null, contentHash };
}

src/integrity/discover.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Supports the identification and organization of files and directories according to integrity policies.</purpose>
<non-goals>
  <item>Do not parse or manipulate the content of files.</item>
  <item>Do not manage Git repository configurations or states.</item>
  <item>Do not provide user interface or command-line functionalities.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Added Compass scaffolding to clarify module purpose and responsibilities.</item>
</CHANGE_SUMMARY>
*/

/**
 * Discover managed files based on integrity policy.
 * Filters Git-tracked files against include/exclude glob patterns.
 */

import path from "node:path";
import { getTrackedFiles } from "./git.ts";
import { loadPolicy, isManagedPath } from "./policy.ts";

export async function discoverManagedFiles(cwd: string): Promise<string[]> {
  const policy = await loadPolicy(cwd);
  const tracked = await getTrackedFiles(cwd);
  return tracked
    .map((filePath) => filePath.replace(/\\/g, "/"))
    .filter((filePath) => isManagedPath(filePath, policy))
    .sort((a, b) => a.localeCompare(b));
}

export async function discoverManagedDirectories(cwd: string): Promise<string[]> {
  const files = await discoverManagedFiles(cwd);
  return Array.from(new Set(files.map((filePath) => path.posix.dirname(filePath)))).sort((a, b) =>
    a.localeCompare(b),
  );
}

export async function groupFilesByDirectory(filePaths: string[]): Promise<Map<string, string[]>> {
  const map = new Map<string, string[]>();
  for (const filePath of filePaths) {
    const dir = path.posix.dirname(filePath);
    const list = map.get(dir) ?? [];
    list.push(filePath);
    map.set(dir, list);
  }
  for (const [dir, list] of map) {
    map.set(
      dir,
      list.sort((a, b) => a.localeCompare(b)),
    );
  }
  return map;
}

