/******************************************************************************* 
<MODULE_CONTRACT> 
<purpose>Facilitates the management of directory manifests to ensure integrity and version tracking of files within specified directories.</purpose> 


<non-goals> 
  <item>Do not parse raw content of manifest files or enforce schema validation.</item> 
  <item>Do not manage the orchestration of transport or configuration settings.</item> 
</non-goals> 
</MODULE_CONTRACT> 

<CHANGE_SUMMARY>
  <item>Enhance Compass scaffolding to accurately reflect the functionality of directory manifest management.</item>
</CHANGE_SUMMARY> 
*******************************************************************************/

/**
 * Directory manifest management for integrity tracking.
 * Loads, saves, and updates per-directory file version manifests.
 */

import path from "node:path";
import { pathExists } from "./fs.ts";
import { readJsonFile, writeJsonFile } from "./json.ts";
import { manifestPathForDirectory } from "./paths.ts";
import type { DirectoryManifest, ManifestFileRecord } from "./types.ts";

export async function loadDirectoryManifest(
  cwd: string,
  repoDir: string,
): Promise<DirectoryManifest | null> {
  const filePath = manifestPathForDirectory(cwd, repoDir);
  if (!(await pathExists(filePath))) return null;
  return readJsonFile<DirectoryManifest>(filePath);
}

export async function saveDirectoryManifest(
  cwd: string,
  manifest: DirectoryManifest,
): Promise<void> {
  const filePath = manifestPathForDirectory(cwd, manifest.directory);
  await writeJsonFile(filePath, manifest);
}

export function createEmptyManifest(repoDir: string): DirectoryManifest {
  return {
    $schemaVersion: 1,
    directory: repoDir,
    generatedAt: new Date().toISOString(),
    files: {},
  };
}

export function upsertManifestRecord(
  manifest: DirectoryManifest,
  fileName: string,
  record: ManifestFileRecord,
): DirectoryManifest {
  manifest.files[fileName] = record;
  manifest.generatedAt = new Date().toISOString();
  return manifest;
}

export function removeManifestRecord(
  manifest: DirectoryManifest,
  fileName: string,
): DirectoryManifest {
  delete manifest.files[fileName];
  manifest.generatedAt = new Date().toISOString();
  return manifest;
}

export function getManifestFileName(repoPath: string): string {
  return path.posix.basename(repoPath);
}

src/integrity/move-detection.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Enables identification of file moves and renames by comparing content hashes, supporting integrity verification.</purpose>
<non-goals>
  <item>Do not perform raw content parsing or analysis beyond hash computation.</item>
  <item>Do not manage file system state or configurations outside of move detection.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Refine Compass scaffolding to accurately reflect the file's architectural role and responsibilities.</item>
  <item>Migrated sha256FileHex from deleted ./hash.ts to byteHashFile from @warpgogol/fingerprint directly.</item>
</CHANGE_SUMMARY>
*/

/**
 * Detect file moves and renames by matching content hashes.
 * Matches deleted and added files to identify moves without content changes.
 */

import path from "node:path";
import { byteHashFile } from "@warpgogol/werkstatt-engine/fingerprint";
import { loadEntitiesById } from "./registry.ts";
import type { MoveCandidate } from "./types.ts";

export async function detectMoves(args: {
  cwd: string;
  deletedPaths: string[];
  addedPaths: string[];
}): Promise<MoveCandidate[]> {
  const { cwd, deletedPaths, addedPaths } = args;
  if (!deletedPaths.length || !addedPaths.length) return [];

  const entities = await loadEntitiesById(cwd);
  const deletedByHash = new Map<string, { entityId: string; from: string }>();

  for (const from of deletedPaths) {
    const entityId = Object.keys(entities).find((id) => entities[id]?.currentPath === from);
    if (!entityId) continue;
    const hash = entities[entityId]?.contentHash;
    if (!hash) continue;
    deletedByHash.set(hash, { entityId, from });
  }

  const moves: MoveCandidate[] = [];
  for (const to of addedPaths) {
    const absPath = path.join(cwd, to);
    const hash = await byteHashFile(absPath).catch(() => null);
    if (!hash) continue;
    const match = deletedByHash.get(hash);
    if (!match) continue;
    moves.push({
      entityId: match.entityId,
      from: match.from,
      to,
      confidence: 1,
      method: "same-hash",
    });
  }

  return moves;
}

