/*
<MODULE_CONTRACT>
<purpose>Facilitates integrity policy management and schema file generation for path validation within the system.</purpose>
<non-goals>
  <item>Do not perform raw content parsing or validation beyond JSON schema definitions.</item>
  <item>Do not manage the orchestration of transport or configuration for policy files.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Refined Compass scaffolding to improve clarity and navigation for future modifications.</item>
</CHANGE_SUMMARY>
*/

/**
 * Integrity policy management and path matching.
 * Defines include/exclude patterns and JSON schemas for validation.
 */

import { pathExists } from "./fs.ts";
import { readJsonFile, writeJsonFile } from "./json.ts";
import { policyPath, schemaDir } from "./paths.ts";
import type { IntegrityPolicy } from "./types.ts";

function escapeRegex(input: string): string {
  return input.replace(/[|\\{}()[\]^$+?.]/g, "\\$&");
}

function globToRegExp(pattern: string): RegExp {
  const normalized = pattern.replace(/\\/g, "/");
  const placeholder = "__DOUBLE_STAR__";
  const source = escapeRegex(normalized)
    .replace(/\*\*/g, placeholder)
    .replace(/\*/g, "[^/]*")
    .replace(new RegExp(placeholder, "g"), ".*");
  return new RegExp(`^${source}$`);
}

const BOOTSTRAP_POLICY = {
  $schemaVersion: 1,
  hashAlgorithm: "sha256",
  include: [
    "src/**",
    "public/**",
    "*.json",
    "**/*.json",
    "*.ts",
    "**/*.ts",
    "*.js",
    "**/*.js",
    "*.astro",
    "**/*.astro",
    "*.md",
    "**/*.md",
    "*.mdx",
    "**/*.mdx",
  ],
  exclude: [
    ".git/**",
    "node_modules/**",
    ".astro/**",
    "dist/**",
    ".idea/**",
    ".vscode/**",
    ".integrity/**",
    "spec/**",
    "todo/**",
  ],
  moveDetection: {
    enableHeuristics: false,
    similarityThreshold: 0.85,
    maxDeletedCandidateAgeHours: 72,
  },
  history: {
    keepDeletedLog: true,
    keepBuildHistory: true,
  },
} satisfies IntegrityPolicy;

const BOOTSTRAP_SCHEMAS = {
  "policy.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/policy.schema.json",
    type: "object",
    additionalProperties: false,
    required: ["$schemaVersion", "hashAlgorithm", "include", "exclude", "moveDetection", "history"],
    properties: {
      $schemaVersion: { const: 1 },
      hashAlgorithm: { const: "sha256" },
      include: { type: "array", items: { type: "string", minLength: 1 } },
      exclude: { type: "array", items: { type: "string", minLength: 1 } },
      moveDetection: {
        type: "object",
        additionalProperties: false,
        required: ["enableHeuristics", "similarityThreshold", "maxDeletedCandidateAgeHours"],
        properties: {
          enableHeuristics: { type: "boolean" },
          similarityThreshold: { type: "number", minimum: 0, maximum: 1 },
          maxDeletedCandidateAgeHours: { type: "integer", minimum: 0 },
        },
      },
      history: {
        type: "object",
        additionalProperties: false,
        required: ["keepDeletedLog", "keepBuildHistory"],
        properties: {
          keepDeletedLog: { type: "boolean" },
          keepBuildHistory: { type: "boolean" },
        },
      },
    },
  },
  "entities.by-id.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/entities.by-id.schema.json",
    type: "object",
    propertyNames: { type: "string", pattern: "^[0-9a-fA-F-]{36}$" },
    additionalProperties: {
      type: "object",
      additionalProperties: false,
      required: [
        "currentPath",
        "createdAt",
        "updatedAt",
        "revision",
        "contentHash",
        "gitSha",
        "status",
      ],
      properties: {
        currentPath: { type: "string", minLength: 1 },
        firstPath: { type: "string", minLength: 1 },
        createdAt: { type: "string", format: "date-time" },
        updatedAt: { type: "string", format: "date-time" },
        revision: { type: "integer", minimum: 1 },
        contentHash: { type: "string", pattern: "^sha256:[0-9a-fA-F]{64}$" },
        gitSha: { type: "string", minLength: 1 },
        status: { enum: ["active", "deleted"] },
        moves: {
          type: "array",
          items: {
            type: "object",
            additionalProperties: false,
            required: ["from", "to", "detectedAt", "confidence", "method"],
            properties: {
              from: { type: "string", minLength: 1 },
              to: { type: "string", minLength: 1 },
              detectedAt: { type: "string", format: "date-time" },
              confidence: { type: "number", minimum: 0, maximum: 1 },
              method: { enum: ["same-hash", "heuristic"] },
            },
          },
        },
      },
    },
  },
  "paths.current.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/paths.current.schema.json",
    type: "object",
    propertyNames: { type: "string", minLength: 1 },
    additionalProperties: { type: "string", pattern: "^[0-9a-fA-F-]{36}$" },
  },
  "deleted-log.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/deleted-log.schema.json",
    type: "array",
    items: {
      type: "object",
      additionalProperties: false,
      required: ["entityId", "lastPath", "deletedAt", "lastRevision", "lastHash"],
      properties: {
        entityId: { type: "string", pattern: "^[0-9a-fA-F-]{36}$" },
        lastPath: { type: "string", minLength: 1 },
        deletedAt: { type: "string", format: "date-time" },
        lastRevision: { type: "integer", minimum: 1 },
        lastHash: { type: "string", pattern: "^sha256:[0-9a-fA-F]{64}$" },
      },
    },
  },
  "manifest.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/manifest.schema.json",
    type: "object",
    additionalProperties: false,
    required: ["$schemaVersion", "directory", "generatedAt", "files"],
    properties: {
      $schemaVersion: { const: 1 },
      directory: { type: "string", minLength: 1 },
      generatedAt: { type: "string", format: "date-time" },
      files: {
        type: "object",
        propertyNames: { type: "string", minLength: 1 },
        additionalProperties: {
          type: "object",
          additionalProperties: false,
          required: [
            "entityId",
            "createdAt",
            "updatedAt",
            "revision",
            "contentHash",
            "gitSha",
            "status",
          ],
          properties: {
            entityId: { type: "string", pattern: "^[0-9a-fA-F-]{36}$" },
            createdAt: { type: "string", format: "date-time" },
            updatedAt: { type: "string", format: "date-time" },
            revision: { type: "integer", minimum: 1 },
            contentHash: { type: "string", pattern: "^sha256:[0-9a-fA-F]{64}$" },
            gitSha: { type: "string", minLength: 1 },
            status: { enum: ["active", "deleted"] },
          },
        },
      },
    },
  },
  "outputs.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/outputs.schema.json",
    type: "object",
    additionalProperties: false,
    required: ["buildId", "outputs"],
    properties: {
      buildId: { type: "string", minLength: 1 },
      outputs: {
        type: "object",
        propertyNames: { type: "string", minLength: 1 },
        additionalProperties: {
          type: "string",
          pattern: "^sha256:[0-9a-fA-F]{64}$",
        },
      },
    },
  },
  "build-provenance.schema.json": {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: "https://example.local/integrity/build-provenance.schema.json",
    type: "object",
    additionalProperties: false,
    required: [
      "buildId",
      "sourceRepo",
      "sourceCommit",
      "builder",
      "buildStartedAt",
      "buildFinishedAt",
      "inputsDigest",
      "outputsDigest",
    ],
    properties: {
      buildId: { type: "string", minLength: 1 },
      sourceRepo: { type: "string", minLength: 1 },
      sourceCommit: { type: "string", minLength: 1 },
      builder: { type: "string", minLength: 1 },
      buildStartedAt: { type: "string", format: "date-time" },
      buildFinishedAt: { type: "string", format: "date-time" },
      inputsDigest: {
        type: "string",
        pattern: "^sha256:[0-9a-fA-F]{64}$",
      },
      outputsDigest: {
        type: "string",
        pattern: "^sha256:[0-9a-fA-F]{64}$",
      },
    },
  },
} as const;

async function ensureSchemaFiles(cwd: string): Promise<void> {
  const root = schemaDir(cwd);

  for (const [fileName, schema] of Object.entries(BOOTSTRAP_SCHEMAS)) {
    const filePath = `${root}/${fileName}`;
    if (await pathExists(filePath)) {
      continue;
    }

    await writeJsonFile(filePath, schema);
  }
}

export async function ensurePolicyFile(cwd: string): Promise<IntegrityPolicy> {
  const filePath = policyPath(cwd);
  await ensureSchemaFiles(cwd);

  if (await pathExists(filePath)) {
    return readJsonFile<IntegrityPolicy>(filePath);
  }

  await writeJsonFile(filePath, BOOTSTRAP_POLICY);
  return BOOTSTRAP_POLICY;
}

export async function loadPolicy(cwd: string): Promise<IntegrityPolicy> {
  return ensurePolicyFile(cwd);
}

export function isManagedPath(repoPath: string, policy: IntegrityPolicy): boolean {
  const normalized = repoPath.replace(/\\/g, "/");
  const excluded = policy.exclude.some((pattern) => globToRegExp(pattern).test(normalized));
  if (excluded) return false;
  return policy.include.some((pattern) => globToRegExp(pattern).test(normalized));
}

src/integrity/registry.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Facilitates management of entity and path registries for integrity tracking.</purpose>
<non-goals>
  <item>Do not handle raw content parsing or validation.</item>
  <item>Do not manage transport or configuration orchestration.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Tidied by compass.changesummary.tidy; see git history for prior entries.</item>
</CHANGE_SUMMARY>
*/

/**
 * Entity and path registry management for integrity tracking.
 * Manages the central entity-by-id and paths-current indexes.
 */

import { pathExists } from "./fs.ts";
import { readJsonFile, writeJsonFile } from "./json.ts";
import { currentPathsPath, entitiesByIdPath } from "./paths.ts";
import type { EntitiesById, PathsCurrent } from "./types.ts";

export async function loadEntitiesById(cwd: string): Promise<EntitiesById> {
  const filePath = entitiesByIdPath(cwd);
  if (!(await pathExists(filePath))) return {};
  return readJsonFile<EntitiesById>(filePath);
}

export async function saveEntitiesById(cwd: string, value: EntitiesById): Promise<void> {
  await writeJsonFile(entitiesByIdPath(cwd), value);
}

export async function loadPathsCurrent(cwd: string): Promise<PathsCurrent> {
  const filePath = currentPathsPath(cwd);
  if (!(await pathExists(filePath))) return {};
  return readJsonFile<PathsCurrent>(filePath);
}

export async function savePathsCurrent(cwd: string, value: PathsCurrent): Promise<void> {
  await writeJsonFile(currentPathsPath(cwd), value);
}

export function bindPath(
  entities: EntitiesById,
  paths: PathsCurrent,
  entityId: string,
  repoPath: string,
): void {
  const previousPath = entities[entityId]?.currentPath;
  if (previousPath && previousPath !== repoPath) {
    delete paths[previousPath];
  }
  paths[repoPath] = entityId;
  if (entities[entityId]) {
    entities[entityId].currentPath = repoPath;
  }
}

export function unbindPath(entities: EntitiesById, paths: PathsCurrent, repoPath: string): void {
  const entityId = paths[repoPath];
  delete paths[repoPath];
  if (entityId && entities[entityId]) {
    entities[entityId].status = "deleted";
  }
}

src/integrity/run-backfill-revisions.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Coordinates the backfilling of revision counts for tracked entities using Git history.</purpose>
<non-goals>
  <item>Do not handle entity creation or deletion beyond revision updates.</item>
  <item>Do not perform any operations related to transport or configuration orchestration.</item>
  <item>Do not parse raw content from files or directories.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Refined the backfill process to ensure accurate revision counts for tracked entities.</item>
</CHANGE_SUMMARY>
*/

/**
 * Annotation revision counts from Git history for all tracked entities.
 * Updates entities and manifests with accurate revision numbers.
 */

import path from "node:path";
import { getFileRevisionFromHistory } from "./git.ts";
import {
  getManifestFileName,
  loadDirectoryManifest,
  saveDirectoryManifest,
  upsertManifestRecord,
} from "./manifests.ts";
import { readJsonFile, writeJsonFile } from "./json.ts";
import { deletedLogPath } from "./paths.ts";
import { loadEntitiesById, loadPathsCurrent, saveEntitiesById } from "./registry.ts";
import type { DeletedLogItem } from "./types.ts";

export async function runBackfillRevisions(args: { cwd: string }): Promise<void> {
  const { cwd } = args;
  const entities = await loadEntitiesById(cwd);
  const paths = await loadPathsCurrent(cwd);
  const deletedLog = await readJsonFile<DeletedLogItem[]>(deletedLogPath(cwd)).catch(() => []);
  const deletedByEntityId = new Map(deletedLog.map((item) => [item.entityId, item]));
  const manifestCache = new Map<string, Awaited<ReturnType<typeof loadDirectoryManifest>>>();

  let updatedEntities = 0;
  let updatedActiveRecords = 0;
  let updatedDeletedLog = 0;

  for (const [entityId, entity] of Object.entries(entities)) {
    const repoPath = entity.currentPath;
    if (!repoPath) {
      continue;
    }

    const revision = await getFileRevisionFromHistory(cwd, repoPath);
    if (revision === entity.revision) {
      continue;
    }

    entity.revision = revision;
    updatedEntities += 1;

    const deletedItem = deletedByEntityId.get(entityId);
    if (deletedItem) {
      deletedItem.lastRevision = revision;
      updatedDeletedLog += 1;
    }

    if (entity.status !== "active" || paths[repoPath] !== entityId) {
      continue;
    }

    const repoDir = path.posix.dirname(repoPath);
    const fileName = getManifestFileName(repoPath);
    let manifest = manifestCache.get(repoDir);
    if (manifest === undefined) {
      manifest = await loadDirectoryManifest(cwd, repoDir);
      manifestCache.set(repoDir, manifest);
    }
    if (!manifest) {
      continue;
    }

    upsertManifestRecord(manifest, fileName, {
      entityId,
      createdAt: entity.createdAt,
      updatedAt: entity.updatedAt,
      revision: entity.revision,
      contentHash: entity.contentHash,
      gitSha: entity.gitSha,
      status: entity.status,
    });
    updatedActiveRecords += 1;
  }

  await saveEntitiesById(cwd, entities);
  await Promise.all(
    Array.from(manifestCache.values())
      .filter((manifest): manifest is NonNullable<typeof manifest> => Boolean(manifest))
      .map((manifest) => saveDirectoryManifest(cwd, manifest)),
  );

  if (updatedDeletedLog > 0) {
    await writeJsonFile(deletedLogPath(cwd), deletedLog);
  }

  console.log("");
  console.log("Integrity revision backfill");
  console.log(`  updated entities      ${updatedEntities}`);
  console.log(`  updated manifest rows ${updatedActiveRecords}`);
  console.log(`  updated deleted log   ${updatedDeletedLog}`);
}

src/integrity/run-init.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Establishes integrity tracking for managed files by creating necessary manifests and entity records.</purpose>
<non-goals>
  <item>Do not perform file content parsing; focus solely on metadata and integrity tracking.</item>
  <item>Do not manage the orchestration of file transport or configuration settings.</item>
  <item>Do not handle user input validation beyond the initial policy file check.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Refine Compass scaffolding to improve clarity and maintainability of the runInit function.</item>
  <item>Migrated sha256FileHex from deleted ./hash.ts to byteHashFile from @warpgogol/fingerprint directly.</item>
</CHANGE_SUMMARY>
*/

/**
 * Initialize integrity tracking by registering all managed files.
 * Creates manifests, entities registry, and path bindings from scratch.
 */

import path from "node:path";
import { byteHashFile } from "@warpgogol/werkstatt-engine/fingerprint";
import { discoverManagedFiles, groupFilesByDirectory } from "./discover.ts";
import { getFileHistory, getFileRevisionFromHistory } from "./git.ts";
import { writeJsonFile } from "./json.ts";
import {
  createEmptyManifest,
  getManifestFileName,
  saveDirectoryManifest,
  upsertManifestRecord,
} from "./manifests.ts";
import { deletedLogPath } from "./paths.ts";
import { saveEntitiesById, savePathsCurrent } from "./registry.ts";
import { v7 as uuidv7 } from "uuid";
import { ensurePolicyFile } from "./policy.ts";
import type { DirectoryManifest, EntitiesById, PathsCurrent } from "./types.ts";

export async function runInit(args: { cwd: string }): Promise<void> {
  const { cwd } = args;
  await ensurePolicyFile(cwd);

  const files = await discoverManagedFiles(cwd);
  const grouped = await groupFilesByDirectory(files);
  const manifests = new Map<string, DirectoryManifest>();
  const entities: EntitiesById = {};
  const paths: PathsCurrent = {};

  for (const file of files) {
    const absPath = path.join(cwd, file);
    const entityId = uuidv7();
    const hash = await byteHashFile(absPath);
    const [history, revision] = await Promise.all([
      getFileHistory(cwd, file),
      getFileRevisionFromHistory(cwd, file),
    ]);
    const now = new Date().toISOString();

    const record = {
      entityId,
      createdAt: history.createdAt ?? now,
      updatedAt: history.updatedAt ?? now,
      revision,
      contentHash: hash,
      gitSha: history.lastCommitSha ?? "unknown",
      status: "active" as const,
    };

    const repoDir = path.posix.dirname(file);
    const fileName = getManifestFileName(file);
    const manifest = manifests.get(repoDir) ?? createEmptyManifest(repoDir);
    upsertManifestRecord(manifest, fileName, record);
    manifests.set(repoDir, manifest);

    entities[entityId] = {
      currentPath: file,
      firstPath: file,
      createdAt: record.createdAt,
      updatedAt: record.updatedAt,
      revision: record.revision,
      contentHash: record.contentHash,
      gitSha: record.gitSha,
      status: "active",
      moves: [],
    };
    paths[file] = entityId;
  }

  for (const repoDir of grouped.keys()) {
    const manifest = manifests.get(repoDir);
    if (manifest) await saveDirectoryManifest(cwd, manifest);
  }

  await saveEntitiesById(cwd, entities);
  await savePathsCurrent(cwd, paths);
  await writeJsonFile(deletedLogPath(cwd), []);

  console.log("");
  console.log("Integrity init");
  console.log(`  managed files       ${files.length}`);
  console.log(`  managed directories ${grouped.size}`);
  console.log(`  registered entities ${Object.keys(entities).length}`);
}

