/******************************************************************************* 
<MODULE_CONTRACT> 
<purpose>Facilitates the recording of build artifacts and generation of provenance metadata.</purpose> 


<non-goals> 
  <item>Do not handle raw content parsing of build files.</item> 
  <item>Do not manage transport or configuration orchestration.</item> 
</non-goals> 
</MODULE_CONTRACT> 

<CHANGE_SUMMARY>
  <item>Tidied by compass.changesummary.tidy; see git history for prior entries.</item>
</CHANGE_SUMMARY> 
*******************************************************************************/

/**
 * Record build artifacts and create provenance metadata.
 * Collects hashes of dist files and stores build metadata for signing.
 */

import { collectBuildOutputs, createBuildProvenance, writeBuildArtifacts } from "./build.ts";

export async function runRecordBuild(args: {
  cwd: string;
  builder?: string;
  distDir?: string;
}): Promise<void> {
  const outputs = await collectBuildOutputs(args.cwd, args.distDir);
  const provenance = await createBuildProvenance({
    cwd: args.cwd,
    builder: args.builder ?? "local",
    outputs,
  });
  await writeBuildArtifacts({ cwd: args.cwd, outputs, provenance });

  console.log("");
  console.log("Integrity build record");
  console.log(`  build id ${outputs.buildId}`);
  console.log(`  outputs  ${Object.keys(outputs.outputs).length}`);
  console.log(`  builder  ${provenance.builder}`);
}

src/integrity/run-update.ts.source:
/* 
<MODULE_CONTRACT>
<purpose>Facilitates the synchronization of integrity manifests with file system changes.</purpose>
<non-goals>
  <item>Do not handle raw file parsing or content validation.</item>
  <item>Do not manage external configuration or transport orchestration.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Migrated sha256FileHex from deleted ./hash.ts to byteHashFile from @warpgogol/fingerprint directly.</item>
</CHANGE_SUMMARY>
*/

/**
 * Update integrity manifests after file system changes.
 * Processes Git changes to update entities, manifests, and path bindings.
 */

import path from "node:path";
import { byteHashFile } from "@warpgogol/werkstatt-engine/fingerprint";
import { discoverManagedFiles } from "./discover.ts";
import { getChangedPaths, getFileHistory } from "./git.ts";
import { readJsonFile, writeJsonFile } from "./json.ts";
import {
  createEmptyManifest,
  getManifestFileName,
  loadDirectoryManifest,
  removeManifestRecord,
  saveDirectoryManifest,
  upsertManifestRecord,
} from "./manifests.ts";
import { deletedLogPath } from "./paths.ts";
import {
  loadEntitiesById,
  loadPathsCurrent,
  saveEntitiesById,
  savePathsCurrent,
} from "./registry.ts";
import { detectMoves } from "./move-detection.ts";
import { v7 as uuidv7 } from "uuid";
import type {
  DeletedLogItem,
  DirectoryManifest,
  EntitiesById,
  ManifestFileRecord,
  MoveCandidate,
  PathsCurrent,
  RegistryEntity,
} from "./types.ts";

function uniqueSorted(values: Iterable<string>): string[] {
  return Array.from(new Set(values)).sort((a, b) => a.localeCompare(b));
}

async function findOutOfSyncActivePaths(args: {
  cwd: string;
  entities: EntitiesById;
  paths: PathsCurrent;
  currentManagedFiles: string[];
}): Promise<string[]> {
  const { cwd, entities, paths, currentManagedFiles } = args;
  const outOfSyncPaths: string[] = [];

  for (const repoPath of currentManagedFiles) {
    const entityId = paths[repoPath];
    if (!entityId) {
      continue;
    }

    const entity = entities[entityId];
    if (!entity || entity.status !== "active") {
      continue;
    }

    const actualHash = await byteHashFile(path.join(cwd, repoPath)).catch(() => null);
    if (!actualHash || actualHash === entity.contentHash) {
      continue;
    }

    outOfSyncPaths.push(repoPath);
  }

  return outOfSyncPaths;
}

function entityToManifestRecord(entityId: string, entity: RegistryEntity): ManifestFileRecord {
  return {
    entityId,
    createdAt: entity.createdAt,
    updatedAt: entity.updatedAt,
    revision: entity.revision,
    contentHash: entity.contentHash,
    gitSha: entity.gitSha,
    status: entity.status,
  };
}

async function loadDeletedLog(cwd: string): Promise<DeletedLogItem[]> {
  return readJsonFile<DeletedLogItem[]>(deletedLogPath(cwd)).catch(() => []);
}

function createManifestStore(cwd: string) {
  const cache = new Map<string, DirectoryManifest>();

  return {
    async get(repoDir: string): Promise<DirectoryManifest> {
      const existing = cache.get(repoDir);
      if (existing) return existing;
      const loaded = (await loadDirectoryManifest(cwd, repoDir)) ?? createEmptyManifest(repoDir);
      cache.set(repoDir, loaded);
      return loaded;
    },
    async saveAll(): Promise<void> {
      for (const manifest of cache.values()) {
        await saveDirectoryManifest(cwd, manifest);
      }
    },
  };
}

async function moveEntity(args: {
  cwd: string;
  entities: EntitiesById;
  paths: PathsCurrent;
  manifestStore: ReturnType<typeof createManifestStore>;
  move: MoveCandidate;
}): Promise<void> {
  const { cwd, entities, paths, manifestStore, move } = args;
  const entity = entities[move.entityId];
  if (!entity) return;

  const oldPath = move.from;
  const newPath = move.to;
  const oldHash = entity.contentHash;
  const absNewPath = path.join(cwd, newPath);
  const nextHash = await byteHashFile(absNewPath).catch(() => oldHash);
  const history = await getFileHistory(cwd, newPath);
  const now = new Date().toISOString();
  const isContentChange = nextHash !== oldHash;

  entity.currentPath = newPath;
  entity.status = "active";
  entity.gitSha = history.lastCommitSha ?? entity.gitSha;

  if (isContentChange) {
    entity.contentHash = nextHash;
    entity.updatedAt = history.updatedAt ?? now;
    entity.revision += 1;
  }

  entity.moves = entity.moves ?? [];
  entity.moves.push({
    from: oldPath,
    to: newPath,
    detectedAt: now,
    confidence: move.confidence,
    method: move.method,
  });

  delete paths[oldPath];
  paths[newPath] = move.entityId;

  const oldDir = path.posix.dirname(oldPath);
  const newDir = path.posix.dirname(newPath);
  const oldFileName = getManifestFileName(oldPath);
  const newFileName = getManifestFileName(newPath);

  const oldManifest = await manifestStore.get(oldDir);
  removeManifestRecord(oldManifest, oldFileName);

  const newManifest = await manifestStore.get(newDir);
  upsertManifestRecord(newManifest, newFileName, entityToManifestRecord(move.entityId, entity));
}

async function markDeleted(args: {
  entities: EntitiesById;
  paths: PathsCurrent;
  deletedLog: DeletedLogItem[];
  manifestStore: ReturnType<typeof createManifestStore>;
  repoPath: string;
}): Promise<void> {
  const { entities, paths, deletedLog, manifestStore, repoPath } = args;
  const entityId = paths[repoPath];
  if (!entityId) return;
  const entity = entities[entityId];
  if (!entity) return;

  entity.status = "deleted";
  delete paths[repoPath];

  deletedLog.push({
    entityId,
    lastPath: repoPath,
    deletedAt: new Date().toISOString(),
    lastRevision: entity.revision,
    lastHash: entity.contentHash,
  });

  const repoDir = path.posix.dirname(repoPath);
  const fileName = getManifestFileName(repoPath);
  const manifest = await manifestStore.get(repoDir);
  removeManifestRecord(manifest, fileName);
}

async function addNewEntity(args: {
  cwd: string;
  entities: EntitiesById;
  paths: PathsCurrent;
  manifestStore: ReturnType<typeof createManifestStore>;
  repoPath: string;
}): Promise<void> {
  const { cwd, entities, paths, manifestStore, repoPath } = args;
  const absPath = path.join(cwd, repoPath);
  const hash = await byteHashFile(absPath);
  const history = await getFileHistory(cwd, repoPath);
  const now = new Date().toISOString();
  const entityId = uuidv7();

  entities[entityId] = {
    currentPath: repoPath,
    firstPath: repoPath,
    createdAt: history.createdAt ?? now,
    updatedAt: history.updatedAt ?? now,
    revision: 1,
    contentHash: hash,
    gitSha: history.lastCommitSha ?? "unknown",
    status: "active",
    moves: [],
  };

  paths[repoPath] = entityId;

  const repoDir = path.posix.dirname(repoPath);
  const fileName = getManifestFileName(repoPath);
  const manifest = await manifestStore.get(repoDir);
  upsertManifestRecord(manifest, fileName, entityToManifestRecord(entityId, entities[entityId]));
}

async function updateModifiedEntity(args: {
  cwd: string;
  entities: EntitiesById;
  paths: PathsCurrent;
  manifestStore: ReturnType<typeof createManifestStore>;
  repoPath: string;
}): Promise<void> {
  const { cwd, entities, paths, manifestStore, repoPath } = args;
  const entityId = paths[repoPath];
  if (!entityId) return;
  const entity = entities[entityId];
  if (!entity || entity.status !== "active") return;

  const absPath = path.join(cwd, repoPath);
  const nextHash = await byteHashFile(absPath);
  if (nextHash === entity.contentHash) return;

  const history = await getFileHistory(cwd, repoPath);
  entity.contentHash = nextHash;
  entity.updatedAt = history.updatedAt ?? new Date().toISOString();
  entity.gitSha = history.lastCommitSha ?? entity.gitSha;
  entity.revision += 1;

  const repoDir = path.posix.dirname(repoPath);
  const fileName = getManifestFileName(repoPath);
  const manifest = await manifestStore.get(repoDir);
  upsertManifestRecord(manifest, fileName, entityToManifestRecord(entityId, entity));
}

export async function runUpdate(args: { cwd: string; baseRef?: string }): Promise<void> {
  const { cwd, baseRef } = args;
  const entities = await loadEntitiesById(cwd);
  const paths = await loadPathsCurrent(cwd);
  const deletedLog = await loadDeletedLog(cwd);
  const manifestStore = createManifestStore(cwd);

  const currentManagedFiles = await discoverManagedFiles(cwd);
  const currentManagedSet = new Set(currentManagedFiles);
  const changes = await getChangedPaths(cwd, baseRef);
  const outOfSyncActivePaths = await findOutOfSyncActivePaths({
    cwd,
    entities,
    paths,
    currentManagedFiles,
  });

  const activePaths = Object.entries(paths)
    .filter(([, entityId]) => entities[entityId]?.status === "active")
    .map(([repoPath]) => repoPath)
    .sort((a, b) => a.localeCompare(b));

  const deletedCandidates = uniqueSorted([
    ...changes.deleted,
    ...activePaths.filter((repoPath) => !currentManagedSet.has(repoPath)),
  ]).filter((repoPath) => paths[repoPath]);

  const addedCandidates = uniqueSorted([
    ...changes.added,
    ...currentManagedFiles.filter((repoPath) => !paths[repoPath]),
  ]).filter((repoPath) => currentManagedSet.has(repoPath));

  const modifiedCandidates = uniqueSorted([
    ...changes.modified,
    ...changes.renamed.map((item) => item.to),
    ...outOfSyncActivePaths,
  ]).filter((repoPath) => currentManagedSet.has(repoPath) && Boolean(paths[repoPath]));

  const matchedDeleted = new Set<string>();
  const matchedAdded = new Set<string>();

  const explicitMoves: MoveCandidate[] = changes.renamed
    .filter(({ from, to }) => Boolean(paths[from]) && currentManagedSet.has(to))
    .map(({ from, to }) => ({
      entityId: paths[from],
      from,
      to,
      confidence: 1,
      method: "heuristic",
    }));

  for (const move of explicitMoves) {
    if (matchedDeleted.has(move.from) || matchedAdded.has(move.to)) continue;
    await moveEntity({ cwd, entities, paths, manifestStore, move });
    matchedDeleted.add(move.from);
    matchedAdded.add(move.to);
  }

  const inferredMoves = await detectMoves({
    cwd,
    deletedPaths: deletedCandidates.filter((repoPath) => !matchedDeleted.has(repoPath)),
    addedPaths: addedCandidates.filter((repoPath) => !matchedAdded.has(repoPath)),
  });

  for (const move of inferredMoves) {
    if (matchedDeleted.has(move.from) || matchedAdded.has(move.to)) continue;
    await moveEntity({ cwd, entities, paths, manifestStore, move });
    matchedDeleted.add(move.from);
    matchedAdded.add(move.to);
  }

  for (const repoPath of deletedCandidates) {
    if (matchedDeleted.has(repoPath)) continue;
    await markDeleted({ entities, paths, deletedLog, manifestStore, repoPath });
  }

  for (const repoPath of addedCandidates) {
    if (matchedAdded.has(repoPath)) continue;
    await addNewEntity({ cwd, entities, paths, manifestStore, repoPath });
  }

  for (const repoPath of modifiedCandidates) {
    if (!paths[repoPath]) continue;
    await updateModifiedEntity({ cwd, entities, paths, manifestStore, repoPath });
  }

  await manifestStore.saveAll();
  await saveEntitiesById(cwd, entities);
  await savePathsCurrent(cwd, paths);
  await writeJsonFile(deletedLogPath(cwd), deletedLog);

  console.log("");
  console.log("Integrity update");
  console.log(`  base ref  ${baseRef ?? "(working tree)"}`);
  console.log(`  added     ${addedCandidates.length - matchedAdded.size}`);
  console.log(`  deleted   ${deletedCandidates.length - matchedDeleted.size}`);
  console.log(`  moved     ${matchedAdded.size}`);
  console.log(`  modified  ${modifiedCandidates.length}`);
}

src/integrity/run-verify.ts.source:
/******************************************************************************* 
<MODULE_CONTRACT> 
<purpose>Facilitates the verification of file integrity against predefined manifests, ensuring compliance with expected standards.</purpose> 


<non-goals> 
  <item>Do not handle raw file parsing or content validation directly.</item> 
  <item>Do not manage configuration or transport orchestration for verification processes.</item> 
</non-goals> 
</MODULE_CONTRACT> 

<CHANGE_SUMMARY>
  <item>Tidied by compass.changesummary.tidy; see git history for prior entries.</item>
</CHANGE_SUMMARY> 
******************************************************************************/

/**
 * Verify integrity of all managed files against stored manifests.
 * Checks hashes, registry consistency, and JSON schema compliance.
 */

import { verifyIntegrity } from "./verify.ts";
import type { VerifyIssue, VerifyReport } from "./types.ts";

function formatIssue(issue: VerifyIssue): string {
  const prefix = issue.level === "error" ? "[ERROR]" : "[WARN ]";
  const location = [issue.path, issue.entityId].filter(Boolean).join(" | ");
  return `${prefix} ${issue.code}: ${issue.message}${location ? ` [${location}]` : ""}`;
}

function printSummary(report: VerifyReport): void {
  const { stats } = report;
  console.log("");
  console.log("Integrity summary");
  console.log(`  managed files       ${stats.managedFiles}`);
  console.log(`  managed directories ${stats.managedDirectories}`);
  console.log(`  manifests loaded    ${stats.manifestsLoaded}`);
  console.log(`  active entities     ${stats.activeEntities}`);
  console.log(`  path bindings       ${stats.activePathBindings}`);
  console.log(`  errors              ${stats.errors}`);
  console.log(`  warnings            ${stats.warnings}`);
}

export async function runVerify(args: { cwd: string }): Promise<VerifyReport> {
  const report = await verifyIntegrity(args.cwd);

  console.log("");
  console.log("Integrity verification report");

  for (const issue of report.issues) {
    console.error(formatIssue(issue));
  }

  printSummary(report);

  if (report.ok) {
    console.log("");
    console.log("Integrity verification passed.");
  } else {
    console.log("");
    console.error("Integrity verification failed.");
  }

  return report;
}

src/integrity/schema-validation.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Facilitates JSON schema validation for integrity files using AJV, ensuring compliance with defined schemas.</purpose>
<non-goals>
  <item>Do not handle schema definition or modification logic.</item>
  <item>Do not parse raw content of JSON files outside validation context.</item>
  <item>Do not manage the lifecycle of AJV instances beyond loading and validation.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Tidied by compass.changesummary.tidy; see git history for prior entries.</item>
</CHANGE_SUMMARY>
*/

/**
 * JSON schema validation for integrity files using AJV.
 * Validates all integrity JSON files against their defined schemas.
 */

import { discoverManagedDirectories } from "./discover.ts";
import { pathExists } from "./fs.ts";
import { readJsonFile } from "./json.ts";
import {
  buildLatestDir,
  currentPathsPath,
  deletedLogPath,
  entitiesByIdPath,
  manifestPathForDirectory,
  outputsPath,
  policyPath,
  provenancePath,
  schemaDir,
} from "./paths.ts";
import type { VerifyIssue } from "./types.ts";

type AjvValidateFunction = {
  (data: unknown): boolean;
  errors?: Array<{ instancePath?: string; message?: string }> | null;
};

interface AjvLike {
  compile(schema: object): AjvValidateFunction;
}

interface LoadedAjv {
  ajv: AjvLike;
  addFormats: (ajv: AjvLike) => void;
}

interface SchemaTarget {
  schemaFile: string;
  dataFile: string;
  pathLabel: string;
  optional?: boolean;
}

function formatAjvErrors(
  errors: Array<{ instancePath?: string; message?: string }> | null | undefined,
): string {
  if (!errors?.length) return "schema validation failed";
  return errors
    .map((error) => `${error.instancePath || "/"} ${error.message ?? "is invalid"}`.trim())
    .join("; ");
}

async function tryLoadAjv(): Promise<LoadedAjv | null> {
  try {
    const [{ default: Ajv2020 }, addFormatsModule] = await Promise.all([
      import("ajv/dist/2020.js"),
      import("ajv-formats"),
    ]);

    const ajv = new Ajv2020({ allErrors: true, strict: false }) as AjvLike;
    const addFormats = (addFormatsModule.default ?? addFormatsModule) as unknown as (
      ajv: AjvLike,
    ) => void;
    addFormats(ajv);

    return { ajv, addFormats };
  } catch {
    return null;
  }
}

async function loadValidator(
  ajv: AjvLike,
  root: string,
  schemaFile: string,
): Promise<AjvValidateFunction> {
  const schema = await readJsonFile<object>(`${root}/${schemaFile}`);
  return ajv.compile(schema);
}

export async function validateIntegrityJsonSchemas(cwd: string): Promise<VerifyIssue[]> {
  const issues: VerifyIssue[] = [];
  const root = schemaDir(cwd);
  const loadedAjv = await tryLoadAjv();

  if (!loadedAjv) {
    issues.push({
      level: "warning",
      code: "SCHEMA_VALIDATION_SKIPPED",
      message:
        "Ajv is not installed, so Draft 2020-12 schema validation was skipped. Structural verification is still active.",
      path: ".integrity/schema",
    });
    return issues;
  }

  const { ajv } = loadedAjv;

  const validatorFiles = [
    "policy.schema.json",
    "entities.by-id.schema.json",
    "paths.current.schema.json",
    "deleted-log.schema.json",
    "manifest.schema.json",
    "outputs.schema.json",
    "build-provenance.schema.json",
  ];

  const validators = new Map<string, AjvValidateFunction>();
  for (const schemaFile of validatorFiles) {
    validators.set(schemaFile, await loadValidator(ajv, root, schemaFile));
  }

  const targets: SchemaTarget[] = [
    {
      schemaFile: "policy.schema.json",
      dataFile: policyPath(cwd),
      pathLabel: ".integrity/config/policy.json",
    },
    {
      schemaFile: "entities.by-id.schema.json",
      dataFile: entitiesByIdPath(cwd),
      pathLabel: ".integrity/index/entities.by-id.json",
    },
    {
      schemaFile: "paths.current.schema.json",
      dataFile: currentPathsPath(cwd),
      pathLabel: ".integrity/index/paths.current.json",
    },
    {
      schemaFile: "deleted-log.schema.json",
      dataFile: deletedLogPath(cwd),
      pathLabel: ".integrity/state/deleted-log.json",
    },
    {
      schemaFile: "outputs.schema.json",
      dataFile: outputsPath(cwd),
      pathLabel: ".integrity/build/latest/outputs.json",
      optional: true,
    },
    {
      schemaFile: "build-provenance.schema.json",
      dataFile: provenancePath(cwd),
      pathLabel: ".integrity/build/latest/build-provenance.json",
      optional: true,
    },
  ];

  const managedDirs = await discoverManagedDirectories(cwd).catch(() => []);
  for (const repoDir of managedDirs) {
    targets.push({
      schemaFile: "manifest.schema.json",
      dataFile: manifestPathForDirectory(cwd, repoDir),
      pathLabel: `.integrity/manifests/${repoDir === "." ? "root" : repoDir}/versions.json`,
    });
  }

  for (const target of targets) {
    const exists = await pathExists(target.dataFile);
    if (!exists) {
      if (target.optional) {
        continue;
      }
      issues.push({
        level: "error",
        code: "SCHEMA_TARGET_MISSING",
        message: "Required integrity JSON file is missing",
        path: target.pathLabel,
      });
      continue;
    }

    let data: unknown;
    try {
      data = await readJsonFile<unknown>(target.dataFile);
    } catch (error) {
      issues.push({
        level: "error",
        code: "INVALID_JSON",
        message: `Failed to parse JSON: ${error instanceof Error ? error.message : String(error)}`,
        path: target.pathLabel,
      });
      continue;
    }

    const validator = validators.get(target.schemaFile);
    if (!validator) {
      issues.push({
        level: "error",
        code: "SCHEMA_VALIDATOR_MISSING",
        message: `Missing validator for ${target.schemaFile}`,
        path: target.pathLabel,
      });
      continue;
    }

    if (!validator(data)) {
      issues.push({
        level: "error",
        code: "SCHEMA_VALIDATION_FAILED",
        message: formatAjvErrors(validator.errors),
        path: target.pathLabel,
      });
    }
  }

  const buildDirExists = await pathExists(buildLatestDir(cwd));
  if (buildDirExists) {
    const hasOutputs = await pathExists(outputsPath(cwd));
    const hasProvenance = await pathExists(provenancePath(cwd));
    if (hasOutputs !== hasProvenance) {
      issues.push({
        level: "error",
        code: "INCOMPLETE_BUILD_LAYER",
        message:
          "Build layer is incomplete: outputs.json and build-provenance.json must exist together",
        path: ".integrity/build/latest",
      });
    }
  }

  return issues;
}

src/integrity/signing.ts.source:
/*
<MODULE_CONTRACT>
  <purpose>Maintains packages/os/site-kernel-integrity/src/signing.ts as an authored site-kernel-integrity authored module so agents can evolve it without rediscovering local boundaries.</purpose>
    <non-goals>
    <item>Do not handle non-cryptographic signing methods.</item>
    <item>Avoid managing non-build related artifacts.</item>
  </non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Migrated sha256StringHex from deleted ./hash.ts to byteHash from @warpgogol/fingerprint directly.</item>
  <item>RFC-0921: delegate signing/verification/keygen to shared signing core. Remove node:crypto sign/verify imports and canonicalJson function.</item>
  <item>RFC-0931: add signBuildIdentity, writeReleasePublicKey, verifyBuildIdentitySignature for Ed25519 signing of build-identity.json in deploy pipeline.</item>
</CHANGE_SUMMARY>

/**
 * Ed25519 cryptographic signing for build artifacts.
 * Provides key generation, payload signing, signature verification, and manifest handling.
 */

import path from "node:path";
import { byteHash } from "@warpgogol/werkstatt-engine/fingerprint";
import {
  generateKeyPair as signingGenerateKeyPair,
  toPem as signingToPem,
  toHex as signingToHex,
  getPublicKey as signingGetPublicKey,
  privateKeyPemToBytes,
  publicKeyPemToBytes,
  sign as signingSign,
  verify as signingVerify,
  canonicalBytes as signingCanonicalBytes,
  fromHex as signingFromHex,
} from "@warpgogol/werkstatt-engine/signing";
import { atomicWriteFile } from "../werkstatt/atomic.ts";
import { ensureDir, pathExists, readBuffer, readText, writeText } from "./fs.ts";
import { readJsonFile, stableStringify } from "./json.ts";
import {
  buildLatestDir,
  outputsPath,
  provenancePath,
  signedManifestPath,
  signatureBinaryPath,
  signatureHexPath,
} from "./paths.ts";
import type { BuildProvenance, OutputsFile, SignablePayload, SignedManifest } from "./types.ts";

let dotEnvLoadedForCwd: string | undefined;

export interface SigningKeyPairPem {
  privateKeyPem: string;
  publicKeyPem: string;
}

export interface ReleaseSignatureArtifacts {
  outputs: OutputsFile;
  provenance: BuildProvenance;
  payload: SignablePayload;
  payloadBytes: Buffer;
  signatureBuffer: Buffer;
  signatureHex: string;
  signedManifest: SignedManifest;
  reusedExistingSignature: boolean;
}

function pemFromBase64(label: "PRIVATE KEY" | "PUBLIC KEY", base64Value: string): string {
  const normalized = base64Value.replace(/\s+/g, "");
  const lines = normalized.match(/.{1,64}/g) ?? [normalized];
  return `-----BEGIN ${label}-----\n${lines.join("\n")}\n-----END ${label}-----\n`;
}

function normalizePemLikeValue(value: string, label: "PRIVATE KEY" | "PUBLIC KEY"): string {
  const trimmed = value.trim();
  if (trimmed.includes("-----BEGIN")) {
    return trimmed.endsWith("\n") ? trimmed : `${trimmed}\n`;
  }
  return pemFromBase64(label, trimmed);
}

async function loadDotEnv(cwd: string): Promise<void> {
  if (dotEnvLoadedForCwd === cwd) {
    return;
  }

  const envPath = path.join(cwd, ".env");
  if (!(await pathExists(envPath))) {
    dotEnvLoadedForCwd = cwd;
    return;
  }

  const envText = await readText(envPath);
  for (const rawLine of envText.split(/\r?\n/u)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) {
      continue;
    }

    const separatorIndex = line.indexOf("=");
    if (separatorIndex <= 0) {
      continue;
    }

    const key = line.slice(0, separatorIndex).trim();
    if (!key || process.env[key] !== undefined) {
      continue;
    }

    let value = line.slice(separatorIndex + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }

    value = value.replace(/\\n/g, "\n");
    process.env[key] = value;
  }

  dotEnvLoadedForCwd = cwd;
}

export async function requireEnv(name: string, cwd = process.cwd()): Promise<string> {
  await loadDotEnv(cwd);
  const value = process.env[name];
  if (!value) {
    throw new Error(`Required environment variable ${name} is not set.`);
  }
  return value;
}

export async function optionalEnv(name: string, cwd = process.cwd()): Promise<string | undefined> {
  await loadDotEnv(cwd);
  return process.env[name] ?? undefined;
}

export async function generateSigningKeyPairPemAsync(): Promise<SigningKeyPairPem> {
  const keyPair = await signingGenerateKeyPair();
  return {
    privateKeyPem: signingToPem(keyPair.privateKey, "private"),
    publicKeyPem: signingToPem(keyPair.publicKey, "public"),
  };
}

export async function loadBuildArtifactsForSigning(cwd: string): Promise<{
  outputs: OutputsFile;
  outputsRaw: string;
  provenance: BuildProvenance;
  provenanceRaw: string;
}> {
  const [outputsRaw, provenanceRaw, outputs, provenance] = await Promise.all([
    readText(outputsPath(cwd)),
    readText(provenancePath(cwd)),
    readJsonFile<OutputsFile>(outputsPath(cwd)),
    readJsonFile<BuildProvenance>(provenancePath(cwd)),
  ]);

  return {
    outputs,
    outputsRaw,
    provenance,
    provenanceRaw,
  };
}

export function createSignablePayload(args: {
  buildId: string;
  outputsRaw: string;
  provenanceRaw: string;
  signedAt?: string;
}): SignablePayload {
  return {
    payloadVersion: "1",
    buildId: args.buildId,
    signedAt: args.signedAt ?? new Date().toISOString(),
    outputsDigest: byteHash(args.outputsRaw).slice("sha256:".length),
    provenanceDigest: byteHash(args.provenanceRaw).slice("sha256:".length),
  };
}

export async function signJsonPayloadAsync(
  privateKeyPem: string,
  payload: Record<string, unknown>,
): Promise<{
  payloadBytes: Buffer;
  signatureBuffer: Buffer;
  signatureHex: string;
  signatureBase64: string;
}> {
  const privateKeyBytes = privateKeyPemToBytes(privateKeyPem);
  const payloadBytes = Buffer.from(signingCanonicalBytes(payload));
  const signatureBytes = await signingSign(privateKeyBytes, payload);
  const signatureBuffer = Buffer.from(signatureBytes);
  return {
    payloadBytes,
    signatureBuffer,
    signatureHex: signatureBuffer.toString("hex"),
    signatureBase64: signatureBuffer.toString("base64"),
  };
}

export async function signLatestBuildArtifacts(args: {
  cwd: string;
  privateKeyPem: string;
  publicKeyUrl?: string;
}): Promise<ReleaseSignatureArtifacts> {
  const { outputs, outputsRaw, provenance, provenanceRaw } = await loadBuildArtifactsForSigning(
    args.cwd,
  );

  if (!provenance.buildId) {
    throw new Error("build-provenance.json is missing buildId. Run integrity:build-record again.");
  }

  const nextPayload = createSignablePayload({
    buildId: provenance.buildId,
    outputsRaw,
    provenanceRaw,
  });

  const existingManifestPath = signedManifestPath(args.cwd);
  if (await pathExists(existingManifestPath)) {
    const existingManifest = await readJsonFile<SignedManifest>(existingManifestPath);
    const digestsMatch =
      existingManifest.buildId === nextPayload.buildId &&
      existingManifest.payload.outputsDigest === nextPayload.outputsDigest &&
      existingManifest.payload.provenanceDigest === nextPayload.provenanceDigest;

    if (digestsMatch) {
      const existingPayloadBytes = Buffer.from(
        signingCanonicalBytes(existingManifest.payload as unknown as Record<string, unknown>),
      );
      const existingSignatureBuffer = Buffer.from(existingManifest.signatureHex, "hex");

      return {
        outputs,
        provenance,
        payload: existingManifest.payload,
        payloadBytes: existingPayloadBytes,
        signatureBuffer: existingSignatureBuffer,
        signatureHex: existingManifest.signatureHex,
        signedManifest: existingManifest,
        reusedExistingSignature: true,
      };
    }
  }

  const signed = await signJsonPayloadAsync(
    args.privateKeyPem,
    nextPayload as unknown as Record<string, unknown>,
  );

  const signedManifest: SignedManifest = {
    buildId: nextPayload.buildId,
    signedAt: nextPayload.signedAt,
    algorithm: "Ed25519",
    payloadVersion: "1",
    payload: nextPayload,
    signatureHex: signed.signatureHex,
    signatureBase64: signed.signatureBase64,
    publicKeyUrl: args.publicKeyUrl,
  };

  await ensureDir(buildLatestDir(args.cwd));
  await Promise.all([
    writeText(signatureHexPath(args.cwd), `${signed.signatureHex}\n`),
    writeText(signedManifestPath(args.cwd), stableStringify(signedManifest)),
  ]);
  await import("node:fs/promises").then(({ writeFile }) =>
    writeFile(signatureBinaryPath(args.cwd), signed.signatureBuffer),
  );

  return {
    outputs,
    provenance,
    payload: nextPayload,
    payloadBytes: signed.payloadBytes,
    signatureBuffer: signed.signatureBuffer,
    signatureHex: signed.signatureHex,
    signedManifest,
    reusedExistingSignature: false,
  };
}

export async function loadSignedManifest(manifestSource: string): Promise<SignedManifest> {
  if (manifestSource.startsWith("https://") || manifestSource.startsWith("http://")) {
    const response = await fetch(manifestSource);
    if (!response.ok) {
      throw new Error(
        `HTTP ${response.status} while fetching signed manifest from ${manifestSource}`,
      );
    }
    return (await response.json()) as SignedManifest;
  }

  return readJsonFile<SignedManifest>(manifestSource);
}

export async function loadPublicKeyPem(args: {
  manifest: SignedManifest;
  publicKeyPemPath?: string;
  publicKeyUrl?: string;
}): Promise<string> {
  if (args.publicKeyPemPath) {
    return normalizePemLikeValue(await readText(path.resolve(args.publicKeyPemPath)), "PUBLIC KEY");
  }

  const publicKeyUrl = args.publicKeyUrl ?? args.manifest.publicKeyUrl;
  if (!publicKeyUrl) {
    throw new Error(
      "No public key source provided. Set PUBLIC_KEY_PEM_PATH, PUBLIC_KEY_URL, or embed publicKeyUrl in signed-manifest.json.",
    );
  }

  const response = await fetch(publicKeyUrl);
  if (!response.ok) {
    throw new Error(`HTTP ${response.status} while fetching public key from ${publicKeyUrl}`);
  }

  return normalizePemLikeValue(await response.text(), "PUBLIC KEY");
}

export function verifyManifestSignature(args: {
  manifest: SignedManifest;
  publicKeyPem: string;
}): Promise<boolean> {
  return verifyJsonSignatureAsync({
    payload: args.manifest.payload as unknown as Record<string, unknown>,
    signatureHex: args.manifest.signatureHex,
    publicKeyPem: args.publicKeyPem,
  });
}

export async function verifyJsonSignatureAsync(args: {
  payload: Record<string, unknown>;
  signatureHex: string;
  publicKeyPem: string;
}): Promise<boolean> {
  const publicKeyBytes = publicKeyPemToBytes(args.publicKeyPem);
  const signatureBytes = signingFromHex(args.signatureHex);
  return signingVerify(publicKeyBytes, args.payload, signatureBytes);
}

export async function compareManifestWithLocalArtifacts(
  cwd: string,
  manifest: SignedManifest,
): Promise<{
  outputsDigestActual: string;
  provenanceDigestActual: string;
  outputsDigestMatches: boolean;
  provenanceDigestMatches: boolean;
}> {
  const [outputsRaw, provenanceRaw] = await Promise.all([
    readText(outputsPath(cwd)),
    readText(provenancePath(cwd)),
  ]);

  const outputsDigestActual = byteHash(outputsRaw).slice("sha256:".length);
  const provenanceDigestActual = byteHash(provenanceRaw).slice("sha256:".length);

  return {
    outputsDigestActual,
    provenanceDigestActual,
    outputsDigestMatches: outputsDigestActual === manifest.payload.outputsDigest,
    provenanceDigestMatches: provenanceDigestActual === manifest.payload.provenanceDigest,
  };
}

export async function readSignatureBinary(cwd: string): Promise<Buffer> {
  return readBuffer(signatureBinaryPath(cwd));
}

/* --- RFC-0931: build-identity.json signing --- */

const SIGNATURE_FIELDS = ["signature", "publicKeyUrl", "signedAt"] as const;

export interface BuildIdentitySignResult {
  signatureHex: string;
  publicKeyHex: string;
  publicKeyUrl: string | null;
  signedAt: string;
  reusedExistingSignature: boolean;
}

export async function signBuildIdentity(args: {
  buildIdentityPath: string;
  privateKeyBytes: Uint8Array;
  publicKeyUrl?: string;
}): Promise<BuildIdentitySignResult> {
  const raw = await readText(args.buildIdentityPath);
  const identity = JSON.parse(raw) as Record<string, unknown>;

  const signablePayload: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(identity)) {
    if (!SIGNATURE_FIELDS.includes(key as (typeof SIGNATURE_FIELDS)[number])) {
      signablePayload[key] = value;
    }
  }

  const existingSignature = typeof identity.signature === "string" ? identity.signature : null;
  const existingSignedAt = typeof identity.signedAt === "string" ? identity.signedAt : null;
  const existingPublicKeyUrl =
    typeof identity.publicKeyUrl === "string" ? identity.publicKeyUrl : null;

  if (existingSignature && existingSignedAt) {
    const publicKeyBytes = await signingGetPublicKey(args.privateKeyBytes);
    const signatureBytes = signingFromHex(existingSignature);
    const isValid = await signingVerify(publicKeyBytes, signablePayload, signatureBytes);

    if (isValid) {
      const publicKeyHex = signingToHex(publicKeyBytes);
      return {
        signatureHex: existingSignature,
        publicKeyHex,
        publicKeyUrl: existingPublicKeyUrl ?? args.publicKeyUrl ?? null,
        signedAt: existingSignedAt,
        reusedExistingSignature: true,
      };
    }
  }

  const signatureBytes = await signingSign(args.privateKeyBytes, signablePayload);
  const signatureHex = Buffer.from(signatureBytes).toString("hex");
  const publicKeyHex = signingToHex(await signingGetPublicKey(args.privateKeyBytes));
  const signedAt = new Date().toISOString();

  const signed: Record<string, unknown> = {
    ...signablePayload,
    signature: signatureHex,
    publicKeyUrl: args.publicKeyUrl ?? null,
    signedAt,
  };

  await atomicWriteFile(args.buildIdentityPath, JSON.stringify(signed, null, 2));

  return {
    signatureHex,
    publicKeyHex,
    publicKeyUrl: args.publicKeyUrl ?? null,
    signedAt,
    reusedExistingSignature: false,
  };
}

export async function writeReleasePublicKey(args: {
  distDir: string;
  publicKeyHex: string;
}): Promise<string> {
  const wellKnownDir = path.join(args.distDir, "client", ".well-known");
  await ensureDir(wellKnownDir);
  const pubKeyPath = path.join(wellKnownDir, "release-pubkey.json");
  const keyId = byteHash(args.publicKeyHex).slice("sha256:".length);
  const content = {
    keyId,
    publicKeyHex: args.publicKeyHex,
    algorithm: "Ed25519",
    createdAt: new Date().toISOString(),
  };
  await atomicWriteFile(pubKeyPath, JSON.stringify(content, null, 2));
  return pubKeyPath;
}

export async function verifyBuildIdentitySignature(args: {
  buildIdentity: Record<string, unknown>;
  publicKeyHex: string;
}): Promise<boolean> {
  const signature =
    typeof args.buildIdentity.signature === "string" ? args.buildIdentity.signature : null;
  if (!signature) return false;

  const signablePayload: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(args.buildIdentity)) {
    if (!SIGNATURE_FIELDS.includes(key as (typeof SIGNATURE_FIELDS)[number])) {
      signablePayload[key] = value;
    }
  }

  const publicKeyBytes = signingFromHex(args.publicKeyHex);
  const signatureBytes = signingFromHex(signature);
  return signingVerify(publicKeyBytes, signablePayload, signatureBytes);
}

src/integrity/verify.ts.source:
/*
<MODULE_CONTRACT>
<purpose>Facilitates integrity verification of managed files against their manifests and registry records.</purpose>
<non-goals>
  <item>Do not handle file content parsing or transformation.</item>
  <item>Do not manage the lifecycle of registry entities.</item>
  <item>Do not perform network operations for data retrieval.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Migrated sha256FileHex from deleted ./hash.ts to byteHashFile from @warpgogol/fingerprint directly.</item>
</CHANGE_SUMMARY>
*/

/**
 * Core integrity verification logic.
 * Validates file hashes against manifests and checks registry consistency.
 */

import path from "node:path";
import { byteHashFile } from "@warpgogol/werkstatt-engine/fingerprint";
import { discoverManagedDirectories, discoverManagedFiles } from "./discover.ts";
import { pathExists } from "./fs.ts";
import { getManifestFileName, loadDirectoryManifest } from "./manifests.ts";
import { loadEntitiesById, loadPathsCurrent } from "./registry.ts";
import { validateIntegrityJsonSchemas } from "./schema-validation.ts";
import type {
  DirectoryManifest,
  ManifestFileRecord,
  RegistryEntity,
  VerifyIssue,
  VerifyReport,
  VerifyStats,
} from "./types.ts";

function isIsoDateTime(value: string): boolean {
  if (!value) return false;
  return !Number.isNaN(Date.parse(value));
}

function isHexSha256(value: string): boolean {
  return /^sha256:[0-9a-f]{64}$/i.test(value);
}

function pushIssue(
  issues: VerifyIssue[],
  level: "error" | "warning",
  code: string,
  message: string,
  extras: Pick<VerifyIssue, "path" | "entityId"> = {},
): void {
  issues.push({ level, code, message, ...extras });
}

function validateRecordShape(
  issues: VerifyIssue[],
  scope: "manifest" | "registry",
  record: ManifestFileRecord | RegistryEntity,
  filePath: string,
  entityId?: string,
): void {
  if (!isIsoDateTime(record.createdAt)) {
    pushIssue(issues, "error", "INVALID_CREATED_AT", `${scope} has invalid createdAt`, {
      path: filePath,
      entityId,
    });
  }
  if (!isIsoDateTime(record.updatedAt)) {
    pushIssue(issues, "error", "INVALID_UPDATED_AT", `${scope} has invalid updatedAt`, {
      path: filePath,
      entityId,
    });
  }
  if (
    isIsoDateTime(record.createdAt) &&
    isIsoDateTime(record.updatedAt) &&
    record.createdAt > record.updatedAt
  ) {
    pushIssue(
      issues,
      "error",
      "INVALID_TIMESTAMP_ORDER",
      `${scope} createdAt is greater than updatedAt`,
      { path: filePath, entityId },
    );
  }
  if (!Number.isInteger(record.revision) || record.revision < 1) {
    pushIssue(issues, "error", "INVALID_REVISION", `${scope} revision must be an integer >= 1`, {
      path: filePath,
      entityId,
    });
  }
  if (!isHexSha256(record.contentHash)) {
    pushIssue(
      issues,
      "error",
      "INVALID_CONTENT_HASH",
      `${scope} contentHash must match sha256:<64-hex>`,
      { path: filePath, entityId },
    );
  }
  if (!record.gitSha || record.gitSha.length < 7) {
    pushIssue(issues, "warning", "WEAK_GIT_SHA", `${scope} gitSha looks missing or too short`, {
      path: filePath,
      entityId,
    });
  }
}

function compareManifestAndRegistry(
  issues: VerifyIssue[],
  repoPath: string,
  manifestRecord: ManifestFileRecord,
  registryRecord: RegistryEntity,
): void {
  const entityId = manifestRecord.entityId;

  if (registryRecord.status !== "active") {
    pushIssue(
      issues,
      "error",
      "REGISTRY_ENTITY_NOT_ACTIVE",
      "Registry entity for managed file is not active",
      { path: repoPath, entityId },
    );
  }
  if (registryRecord.currentPath !== repoPath) {
    pushIssue(
      issues,
      "error",
      "CURRENT_PATH_MISMATCH",
      "Registry currentPath does not match managed file path",
      { path: repoPath, entityId },
    );
  }
  if (manifestRecord.status !== "active") {
    pushIssue(
      issues,
      "error",
      "MANIFEST_RECORD_NOT_ACTIVE",
      "Manifest record for managed file is not active",
      { path: repoPath, entityId },
    );
  }
  if (manifestRecord.createdAt !== registryRecord.createdAt) {
    pushIssue(issues, "error", "CREATED_AT_MISMATCH", "Manifest and registry createdAt differ", {
      path: repoPath,
      entityId,
    });
  }
  if (manifestRecord.updatedAt !== registryRecord.updatedAt) {
    pushIssue(issues, "error", "UPDATED_AT_MISMATCH", "Manifest and registry updatedAt differ", {
      path: repoPath,
      entityId,
    });
  }
  if (manifestRecord.revision !== registryRecord.revision) {
    pushIssue(issues, "error", "REVISION_MISMATCH", "Manifest and registry revision differ", {
      path: repoPath,
      entityId,
    });
  }
  if (manifestRecord.contentHash !== registryRecord.contentHash) {
    pushIssue(
      issues,
      "error",
      "CONTENT_HASH_MISMATCH_BETWEEN_INDEXES",
      "Manifest and registry contentHash differ",
      { path: repoPath, entityId },
    );
  }
  if (manifestRecord.gitSha !== registryRecord.gitSha) {
    pushIssue(
      issues,
      "warning",
      "GIT_SHA_MISMATCH_BETWEEN_INDEXES",
      "Manifest and registry gitSha differ",
      { path: repoPath, entityId },
    );
  }
}

async function loadExpectedManifests(
  cwd: string,
  managedDirectories: string[],
  issues: VerifyIssue[],
): Promise<Map<string, DirectoryManifest>> {
  const manifests = new Map<string, DirectoryManifest>();

  for (const repoDir of managedDirectories) {
    const manifest = await loadDirectoryManifest(cwd, repoDir);
    if (!manifest) {
      pushIssue(
        issues,
        "error",
        "MISSING_DIRECTORY_MANIFEST",
        "Managed directory is missing versions.json",
        { path: repoDir },
      );
      continue;
    }
    manifests.set(repoDir, manifest);

    if (manifest.$schemaVersion !== 1) {
      pushIssue(
        issues,
        "error",
        "INVALID_MANIFEST_SCHEMA_VERSION",
        "Manifest has unsupported $schemaVersion",
        { path: repoDir },
      );
    }
    if (manifest.directory !== repoDir) {
      pushIssue(
        issues,
        "error",
        "MANIFEST_DIRECTORY_MISMATCH",
        "Manifest directory field does not match directory path",
        { path: repoDir },
      );
    }
    if (!isIsoDateTime(manifest.generatedAt)) {
      pushIssue(
        issues,
        "error",
        "INVALID_MANIFEST_GENERATED_AT",
        "Manifest generatedAt is invalid",
        { path: repoDir },
      );
    }
  }

  return manifests;
}

export async function verifyIntegrity(cwd: string): Promise<VerifyReport> {
  const issues: VerifyIssue[] = [];
  issues.push(...(await validateIntegrityJsonSchemas(cwd)));
  const managedFiles = await discoverManagedFiles(cwd);
  const managedDirectories = await discoverManagedDirectories(cwd);
  const entities = await loadEntitiesById(cwd);
  const paths = await loadPathsCurrent(cwd);
  const manifests = await loadExpectedManifests(cwd, managedDirectories, issues);

  const activeEntities = Object.entries(entities).filter(
    ([, entity]) => entity.status === "active",
  );
  const duplicateEntityIds = new Set<string>();
  const seenEntityIds = new Set<string>();

  for (const [repoPath, entityId] of Object.entries(paths)) {
    if (!managedFiles.includes(repoPath)) {
      const exists = await pathExists(path.join(cwd, repoPath));
      pushIssue(
        issues,
        exists ? "warning" : "error",
        "UNEXPECTED_PATH_BINDING",
        exists
          ? "paths.current contains a binding for a file outside managed scope"
          : "paths.current contains a binding for a missing file",
        { path: repoPath, entityId },
      );
    }
    if (seenEntityIds.has(entityId)) {
      duplicateEntityIds.add(entityId);
    }
    seenEntityIds.add(entityId);
  }

  for (const entityId of duplicateEntityIds) {
    pushIssue(
      issues,
      "error",
      "DUPLICATE_ACTIVE_ENTITY_ID",
      "The same entityId is bound to multiple current paths",
      { entityId },
    );
  }

  for (const file of managedFiles) {
    const entityId = paths[file];
    const absPath = path.join(cwd, file);
    const repoDir = path.posix.dirname(file);
    const fileName = getManifestFileName(file);
    const manifest = manifests.get(repoDir);

    if (!entityId) {
      pushIssue(
        issues,
        "error",
        "MISSING_PATH_BINDING",
        "Managed file is missing from paths.current index",
        { path: file },
      );
      continue;
    }

    const entity = entities[entityId];
    if (!entity) {
      pushIssue(
        issues,
        "error",
        "MISSING_REGISTRY_ENTITY",
        "Path binding points to absent registry entity",
        { path: file, entityId },
      );
      continue;
    }

    validateRecordShape(issues, "registry", entity, file, entityId);

    if (!manifest) continue;

    const manifestRecord = manifest.files[fileName];
    if (!manifestRecord) {
      pushIssue(
        issues,
        "error",
        "MISSING_MANIFEST_RECORD",
        "Managed file is missing from its directory manifest",
        { path: file, entityId },
      );
      continue;
    }

    validateRecordShape(issues, "manifest", manifestRecord, file, entityId);

    if (manifestRecord.entityId !== entityId) {
      pushIssue(
        issues,
        "error",
        "ENTITY_ID_MISMATCH",
        "Manifest record entityId differs from paths.current binding",
        { path: file, entityId },
      );
    }

    compareManifestAndRegistry(issues, file, manifestRecord, entity);

    const actualHash = await byteHashFile(absPath);
    if (actualHash !== entity.contentHash) {
      pushIssue(
        issues,
        "error",
        "HASH_MISMATCH_REGISTRY",
        "Actual file hash differs from registry hash",
        { path: file, entityId },
      );
    }
    if (actualHash !== manifestRecord.contentHash) {
      pushIssue(
        issues,
        "error",
        "HASH_MISMATCH_MANIFEST",
        "Actual file hash differs from manifest hash",
        { path: file, entityId },
      );
    }
  }

  for (const [repoDir, manifest] of manifests) {
    for (const [fileName, manifestRecord] of Object.entries(manifest.files)) {
      const repoPath = path.posix.join(repoDir, fileName);
      const entity = entities[manifestRecord.entityId];
      const hasFile = managedFiles.includes(repoPath);

      validateRecordShape(issues, "manifest", manifestRecord, repoPath, manifestRecord.entityId);

      if (!hasFile) {
        const exists = await pathExists(path.join(cwd, repoPath));
        pushIssue(
          issues,
          exists ? "warning" : "error",
          "STALE_MANIFEST_RECORD",
          exists
            ? "Manifest record points to an existing file outside managed scope"
            : "Manifest record points to a missing file",
          { path: repoPath, entityId: manifestRecord.entityId },
        );
      }

      if (!entity) {
        pushIssue(
          issues,
          "error",
          "MANIFEST_ENTITY_MISSING_IN_REGISTRY",
          "Manifest record points to missing registry entity",
          { path: repoPath, entityId: manifestRecord.entityId },
        );
      }
    }
  }

  for (const [entityId, entity] of activeEntities) {
    validateRecordShape(issues, "registry", entity, entity.currentPath, entityId);

    if (!managedFiles.includes(entity.currentPath)) {
      const exists = await pathExists(path.join(cwd, entity.currentPath));
      pushIssue(
        issues,
        exists ? "warning" : "error",
        "ACTIVE_ENTITY_OUTSIDE_SCOPE",
        exists
          ? "Active registry entity points to a file outside managed scope"
          : "Active registry entity points to a missing file",
        { path: entity.currentPath, entityId },
      );
    }

    if (paths[entity.currentPath] !== entityId) {
      pushIssue(
        issues,
        "error",
        "REGISTRY_PATH_NOT_BOUND",
        "Active registry entity currentPath is not correctly bound in paths.current",
        { path: entity.currentPath, entityId },
      );
    }
  }

  const collator = new Intl.Collator("en");
  issues.sort((a, b) => {
    if (a.level !== b.level) return a.level === "error" ? -1 : 1;
    if ((a.code ?? "") !== (b.code ?? "")) return collator.compare(a.code ?? "", b.code ?? "");
    if ((a.path ?? "") !== (b.path ?? "")) return collator.compare(a.path ?? "", b.path ?? "");
    return collator.compare(a.entityId ?? "", b.entityId ?? "");
  });

  const stats: VerifyStats = {
    managedFiles: managedFiles.length,
    managedDirectories: managedDirectories.length,
    manifestsLoaded: manifests.size,
    activeEntities: activeEntities.length,
    activePathBindings: Object.keys(paths).length,
    errors: issues.filter((issue) => issue.level === "error").length,
    warnings: issues.filter((issue) => issue.level === "warning").length,
  };

  return { ok: stats.errors === 0, issues, stats };
}

