/*
<MODULE_CONTRACT>
<purpose>Defines a constant sequence for integrity operations in release processes.</purpose>
<non-goals>
  <item>Do not define the implementation details of each command.</item>
  <item>Do not manage the execution context or orchestration of the pipeline.</item>
</non-goals>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>Clarify module purpose and responsibilities for future reference.</item>
</CHANGE_SUMMARY>
*/

import type { KernelPipelineStep } from "@warpgogol/werkstatt-engine/kernel";

// @ai-invariant STANDARD_INTEGRITY_PIPELINE is the single authoritative ordered sequence for
// integrity release operations. Apps spread this constant into their pipelines to get
// the full workflow: build record → sign → verify release.
export const STANDARD_INTEGRITY_PIPELINE: KernelPipelineStep[] = [
  { command: "integrity.build-record" },
  { command: "integrity.sign" },
  { command: "integrity.verify-release" },
];

src/tests-handoff/leitstand-0995-mirror-.source:
/*
<MODULE_CONTRACT>
  <purpose>
    RFC-0995: unit tests for mirror sync pre-flight check in leitstand.promote —
    verifies warning is logged when external mirrors are out of sync, when mirror
    ref is missing, and that no warning is logged when mirrors are in sync or
    when no external mirrors are configured.
  </purpose>
  <keywords>RFC-0995, leitstand, promote, mirror, sync, pre-flight, warning</keywords>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>RFC-0995: initial tests for checkMirrorSyncPreFlight pure function.</item>
</CHANGE_SUMMARY>
*/

import { test, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, rmSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { execSync } from "node:child_process";
import { tmpdir } from "node:os";
import { checkMirrorSyncPreFlight } from "../leitstand/leitstand-commands.ts";

let testRoot: string;
let workspaceRoot: string;

beforeEach(() => {
  testRoot = mkdtempSync(join(tmpdir(), "tmp-rfc-0995-"));
  workspaceRoot = join(testRoot, "workspace");
  mkdirSync(workspaceRoot, { recursive: true });
});

afterEach(() => {
  rmSync(testRoot, { recursive: true, force: true });
});

function makeBareRepo(barePath: string): void {
  mkdirSync(barePath, { recursive: true });
  execSync("git init --bare -b main", { cwd: barePath, stdio: "pipe" });
}

function commitToBare(barePath: string, msg: string): string {
  const tmpClone = join(testRoot, "tmp-clone-" + Date.now());
  execSync(`git clone "${barePath}" "${tmpClone}"`, { stdio: "pipe" });
  execSync("git config user.email test@test.com", { cwd: tmpClone, stdio: "pipe" });
  execSync("git config user.name Test", { cwd: tmpClone, stdio: "pipe" });
  writeFileSync(join(tmpClone, "README.md"), `# ${msg}\n`);
  execSync("git add -A", { cwd: tmpClone, stdio: "pipe" });
  execSync(`git commit -m ${JSON.stringify(msg)}`, { cwd: tmpClone, stdio: "pipe" });
  execSync("git push origin main", { cwd: tmpClone, stdio: "pipe" });
  const sha = execSync("git rev-parse HEAD", { cwd: tmpClone, encoding: "utf-8" }).trim();
  rmSync(tmpClone, { recursive: true, force: true });
  return sha;
}

function writeSystemConfig(systemId: string, mirrors: Array<{ path: string; storageType: string }>): void {
  const cacheDir = join(testRoot, "systems-cache", systemId);
  mkdirSync(cacheDir, { recursive: true });
  const mirrorsYaml = mirrors.map((m) => `  - path: "${m.path}"\n    storageType: ${m.storageType}`).join("\n");
  const configContent = `schemaVersion: system-config/v1
id: ${systemId}
cosmicStar: Vega
mirrors:
${mirrorsYaml}
pinnedPlatform: "6.0.0"
status: active
registeredAt: "2026-01-01T00:00:00Z"
notes: ""
`;
  writeFileSync(join(cacheDir, "system-config.yaml"), configContent);
}

test("warns when external mirrors are out of sync (originSha !== mirrorSha)", async () => {
  const systemId = "test-sys";
  const barePath = join(testRoot, "systems-cache", `${systemId}.git`);
  makeBareRepo(barePath);

  const sha1 = commitToBare(barePath, "first commit");
  const sha2 = commitToBare(barePath, "second commit");

  // Set refs/mirror/main to the first commit (stale)
  execSync(`git update-ref refs/mirror/main ${sha1}`, { cwd: barePath, stdio: "pipe" });

  writeSystemConfig(systemId, [
    { path: `../systems-cache/${systemId}`, storageType: "non-bare" },
    { path: `../systems-cache/${systemId}.git`, storageType: "bare" },
    { path: "https://github.com/example/repo.git", storageType: "bare" },
  ]);

  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await checkMirrorSyncPreFlight(workspaceRoot, systemId, logger);

  expect(warnings).toHaveLength(1);
  expect(warnings[0]).toContain("external mirrors are out of sync");
  expect(warnings[0]).toContain(`origin=${sha2.slice(0, 8)}`);
  expect(warnings[0]).toContain(`mirror=${sha1.slice(0, 8)}`);
  expect(warnings[0]).toContain(`sternsystem.sync --id ${systemId}`);
});

test("warns when mirror ref not found", async () => {
  const systemId = "test-sys";
  const barePath = join(testRoot, "systems-cache", `${systemId}.git`);
  makeBareRepo(barePath);

  commitToBare(barePath, "first commit");

  // Do NOT set refs/mirror/main — simulates never-synced state

  writeSystemConfig(systemId, [
    { path: `../systems-cache/${systemId}`, storageType: "non-bare" },
    { path: `../systems-cache/${systemId}.git`, storageType: "bare" },
    { path: "https://github.com/example/repo.git", storageType: "bare" },
  ]);

  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await checkMirrorSyncPreFlight(workspaceRoot, systemId, logger);

  expect(warnings).toHaveLength(1);
  expect(warnings[0]).toContain("mirror ref not found");
  expect(warnings[0]).toContain(`sternsystem.sync --id ${systemId}`);
});

test("no warning when mirrors are in sync (originSha === mirrorSha)", async () => {
  const systemId = "test-sys";
  const barePath = join(testRoot, "systems-cache", `${systemId}.git`);
  makeBareRepo(barePath);

  const sha = commitToBare(barePath, "only commit");

  // Set refs/mirror/main to same SHA — mirrors in sync
  execSync(`git update-ref refs/mirror/main ${sha}`, { cwd: barePath, stdio: "pipe" });

  writeSystemConfig(systemId, [
    { path: `../systems-cache/${systemId}`, storageType: "non-bare" },
    { path: `../systems-cache/${systemId}.git`, storageType: "bare" },
    { path: "https://github.com/example/repo.git", storageType: "bare" },
  ]);

  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await checkMirrorSyncPreFlight(workspaceRoot, systemId, logger);

  expect(warnings).toHaveLength(0);
});

test("no warning and no error when no external mirrors configured (mirrors.length <= 2)", async () => {
  const systemId = "test-sys";
  const barePath = join(testRoot, "systems-cache", `${systemId}.git`);
  makeBareRepo(barePath);

  commitToBare(barePath, "commit");

  writeSystemConfig(systemId, [
    { path: `../systems-cache/${systemId}`, storageType: "non-bare" },
    { path: `../systems-cache/${systemId}.git`, storageType: "bare" },
  ]);

  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await checkMirrorSyncPreFlight(workspaceRoot, systemId, logger);

  expect(warnings).toHaveLength(0);
});

test("silently skips when system config not found", async () => {
  const systemId = "nonexistent-sys";
  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await expect(checkMirrorSyncPreFlight(workspaceRoot, systemId, logger)).resolves.toBeUndefined();
  expect(warnings).toHaveLength(0);
});

test("silently skips when bare repo does not exist", async () => {
  const systemId = "test-sys";
  // No bare repo created

  writeSystemConfig(systemId, [
    { path: `../systems-cache/${systemId}`, storageType: "non-bare" },
    { path: `../systems-cache/${systemId}.git`, storageType: "bare" },
    { path: "https://github.com/example/repo.git", storageType: "bare" },
  ]);

  const warnings: string[] = [];
  const logger = { warn: (msg: string) => warnings.push(msg) };

  await checkMirrorSyncPreFlight(workspaceRoot, systemId, logger);

  expect(warnings).toHaveLength(0);
});

src/leitstand/tests/leitstand-sign.test..source:
/*
<MODULE_CONTRACT>
  <purpose>RFC-0931: unit tests for build-identity.json signing, release-pubkey.json writing, and signature verification.</purpose>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>RFC-0931: initial tests for signBuildIdentity, writeReleasePublicKey, verifyBuildIdentitySignature, and leitstand.verify --verify-signature.</item>
</CHANGE_SUMMARY>
*/

import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import { mkdtempSync, writeFileSync, readFileSync, existsSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import {
  signBuildIdentity,
  writeReleasePublicKey,
  verifyBuildIdentitySignature,
} from "../../integrity/signing.ts";
import { generateKeyPair, toHex } from "@warpgogol/werkstatt-engine/signing";

vi.mock("../../sternsystem/registry-io.ts", () => ({
  readSystemConfigSmart: vi.fn(),
  readSystemStateSmart: vi.fn(),
  resolveCacheClonePath: vi.fn(),
}));

const { runLeitstandVerify } = await import("../leitstand-commands.ts");
const { readSystemConfigSmart, readSystemStateSmart } =
  await import("../../sternsystem/registry-io.ts");

function makeInput(flags: Record<string, unknown>) {
  return { flags, args: [] } as unknown as Parameters<typeof runLeitstandVerify>[0];
}

function makeContext(workspaceRoot: string) {
  return { workspaceRoot, dryRun: false, site: undefined } as unknown as Parameters<
    typeof runLeitstandVerify
  >[1];
}

const defaultConfig = {
  schemaVersion: "1.0.0",
  id: "test-site",
  deployment: {
    adapter: "cloudflare-workers" as const,
    channels: {
      dev: { workerName: "dev-test", url: "https://dev.test.com" },
      alt: { workerName: "alt-test", url: "https://alt.test.com" },
      main: { workerName: "test", url: "https://test.com" },
    },
  },
};

const defaultState = {
  schemaVersion: "1.0.0",
  systemId: "test-site",
  currentMission: null,
  lastRelease: null,
  lastPropagated: {
    dev: {
      releaseId: "r000005",
      at: "2026-08-23T12:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-1",
      leaseExpiresAt: null,
    },
    alt: {
      releaseId: "r000005",
      at: "2026-08-23T13:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-2",
      leaseExpiresAt: null,
    },
    main: {
      releaseId: "r000005",
      at: "2026-08-23T14:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-3",
      leaseExpiresAt: null,
    },
  },
  accessPin: null as string | null,
};

function mockBuildIdentity(distTreeHash: string, releaseId = "r000005") {
  return JSON.stringify({
    distTreeHash,
    releaseId,
    missionId: "m000076",
    buildTimestamp: "2026-08-23T12:45:06Z",
  });
}

let tmpDir: string;
let keyPair: { privateKey: Uint8Array; publicKey: Uint8Array };

beforeEach(async () => {
  tmpDir = mkdtempSync(join(tmpdir(), "leitstand-sign-"));
  keyPair = await generateKeyPair();
});

afterEach(() => {
  vi.restoreAllMocks();
});

describe("RFC-0931: signBuildIdentity", () => {
  it("signs build-identity.json and embeds signature, publicKeyUrl, signedAt", async () => {
    const idPath = join(tmpDir, "build-identity.json");
    writeFileSync(
      idPath,
      JSON.stringify({
        releaseId: "test-r000001",
        systemId: "test-site",
        missionId: "m000001",
        semver: "1.0.0",
        distTreeHash: "sha256:abc",
        behaviorSnapshotHash: "sha256:def",
        siteContentHash: "sha256:ghi",
        platformVersion: "6.0.0",
        platformSemanticHash: "sha256:sem",
        commitSha: "abc123",
        buildTimestamp: "2026-08-23T12:00:00.000Z",
        targetPlatform: "cloudflare",
      }),
    );

    const result = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
      publicKeyUrl: "https://example.com/.well-known/release-pubkey.json",
    });

    expect(result.signatureHex).toMatch(/^[0-9a-f]{128}$/);
    expect(result.publicKeyHex).toMatch(/^[0-9a-f]{64}$/);
    expect(result.publicKeyUrl).toBe("https://example.com/.well-known/release-pubkey.json");
    expect(result.signedAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
    expect(result.reusedExistingSignature).toBe(false);

    const signed = JSON.parse(readFileSync(idPath, "utf8"));
    expect(signed.signature).toBe(result.signatureHex);
    expect(signed.publicKeyUrl).toBe("https://example.com/.well-known/release-pubkey.json");
    expect(signed.signedAt).toBe(result.signedAt);
    expect(signed.distTreeHash).toBe("sha256:abc");
  });

  it("reuses existing signature when payload hasn't changed (idempotency)", async () => {
    const idPath = join(tmpDir, "build-identity.json");
    const baseIdentity = {
      releaseId: "test-r000001",
      systemId: "test-site",
      missionId: "m000001",
      semver: "1.0.0",
      distTreeHash: "sha256:abc",
      behaviorSnapshotHash: "sha256:def",
      siteContentHash: "sha256:ghi",
      platformVersion: "6.0.0",
      platformSemanticHash: "sha256:sem",
      commitSha: "abc123",
      buildTimestamp: "2026-08-23T12:00:00.000Z",
      targetPlatform: "cloudflare",
    };
    writeFileSync(idPath, JSON.stringify(baseIdentity));

    const first = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    const second = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    expect(second.reusedExistingSignature).toBe(true);
    expect(second.signatureHex).toBe(first.signatureHex);
  });

  it("produces new signature when payload has changed", async () => {
    const idPath = join(tmpDir, "build-identity.json");
    writeFileSync(
      idPath,
      JSON.stringify({
        releaseId: "test-r000001",
        systemId: "test-site",
        missionId: "m000001",
        semver: "1.0.0",
        distTreeHash: "sha256:abc",
        behaviorSnapshotHash: "sha256:def",
        siteContentHash: "sha256:ghi",
        platformVersion: "6.0.0",
        platformSemanticHash: "sha256:sem",
        commitSha: "abc123",
        buildTimestamp: "2026-08-23T12:00:00.000Z",
        targetPlatform: "cloudflare",
      }),
    );

    const first = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    // Modify payload
    const signed = JSON.parse(readFileSync(idPath, "utf8"));
    signed.distTreeHash = "sha256:changed";
    writeFileSync(idPath, JSON.stringify(signed));

    const second = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    expect(second.reusedExistingSignature).toBe(false);
    expect(second.signatureHex).not.toBe(first.signatureHex);
  });
});

describe("RFC-0931: writeReleasePublicKey", () => {
  it("writes release-pubkey.json to dist/client/.well-known/", async () => {
    const distDir = join(tmpDir, "dist");
    const publicKeyHex = toHex(keyPair.publicKey);

    const result = await writeReleasePublicKey({ distDir, publicKeyHex });

    expect(existsSync(result)).toBe(true);
    const content = JSON.parse(readFileSync(result, "utf8"));
    expect(content.publicKeyHex).toBe(publicKeyHex);
    expect(content.algorithm).toBe("Ed25519");
    expect(content.keyId).toMatch(/^[0-9a-f]{64}$/);
    expect(content.createdAt).toMatch(/^\d{4}-\d{2}-\d{2}T/);
  });
});

describe("RFC-0931: verifyBuildIdentitySignature", () => {
  it("verifies a valid signature", async () => {
    const idPath = join(tmpDir, "build-identity.json");
    const identity = {
      releaseId: "test-r000001",
      systemId: "test-site",
      missionId: "m000001",
      semver: "1.0.0",
      distTreeHash: "sha256:abc",
      behaviorSnapshotHash: "sha256:def",
      siteContentHash: "sha256:ghi",
      platformVersion: "6.0.0",
      platformSemanticHash: "sha256:sem",
      commitSha: "abc123",
      buildTimestamp: "2026-08-23T12:00:00.000Z",
      targetPlatform: "cloudflare",
    };
    writeFileSync(idPath, JSON.stringify(identity));

    const signResult = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    const signedIdentity = JSON.parse(readFileSync(idPath, "utf8"));
    const valid = await verifyBuildIdentitySignature({
      buildIdentity: signedIdentity,
      publicKeyHex: signResult.publicKeyHex,
    });

    expect(valid).toBe(true);
  });

  it("rejects tampered build-identity.json", async () => {
    const idPath = join(tmpDir, "build-identity.json");
    writeFileSync(
      idPath,
      JSON.stringify({
        releaseId: "test-r000001",
        systemId: "test-site",
        missionId: "m000001",
        semver: "1.0.0",
        distTreeHash: "sha256:abc",
        behaviorSnapshotHash: "sha256:def",
        siteContentHash: "sha256:ghi",
        platformVersion: "6.0.0",
        platformSemanticHash: "sha256:sem",
        commitSha: "abc123",
        buildTimestamp: "2026-08-23T12:00:00.000Z",
        targetPlatform: "cloudflare",
      }),
    );

    const signResult = await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: keyPair.privateKey,
    });

    const signedIdentity = JSON.parse(readFileSync(idPath, "utf8"));
    signedIdentity.distTreeHash = "sha256:tampered";

    const valid = await verifyBuildIdentitySignature({
      buildIdentity: signedIdentity,
      publicKeyHex: signResult.publicKeyHex,
    });

    expect(valid).toBe(false);
  });

  it("returns false when no signature present", async () => {
    const valid = await verifyBuildIdentitySignature({
      buildIdentity: { releaseId: "test", distTreeHash: "sha256:abc" },
      publicKeyHex: toHex(keyPair.publicKey),
    });

    expect(valid).toBe(false);
  });
});

describe("RFC-0931: leitstand.verify --verify-signature", () => {
  it("signatureValid is null when --verify-signature is not set", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc123"), { status: 200 })),
    );

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    for (const ch of result.data!.channels) {
      expect(ch.signatureValid).toBeNull();
      expect(ch.publicKeyUrl).toBeNull();
    }
  });

  it("signatureValid is true when signature matches public key", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);

    const kp = await generateKeyPair();
    const pubKeyHex = toHex(kp.publicKey);

    // Create signed build-identity
    const identity = {
      distTreeHash: "sha256:abc123",
      releaseId: "r000005",
      missionId: "m000076",
      buildTimestamp: "2026-08-23T12:45:06Z",
    };
    const idPath = join(tmpDir, "build-identity.json");
    writeFileSync(idPath, JSON.stringify(identity));
    await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: kp.privateKey,
    });
    const signedIdentity = JSON.parse(readFileSync(idPath, "utf8"));

    const pubKeyJson = JSON.stringify({
      keyId: "test-key-id",
      publicKeyHex: pubKeyHex,
      algorithm: "Ed25519",
      createdAt: "2026-08-23T12:00:00.000Z",
    });

    vi.spyOn(globalThis, "fetch").mockImplementation((url: string | URL | Request) => {
      const urlStr = typeof url === "string" ? url : url.toString();
      if (urlStr.includes("release-pubkey.json")) {
        return Promise.resolve(new Response(pubKeyJson, { status: 200 }));
      }
      // build-identity.json fetch — return signed version
      return Promise.resolve(new Response(JSON.stringify(signedIdentity), { status: 200 }));
    });

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "verify-signature": true }),
      makeContext("/tmp"),
    );

    for (const ch of result.data!.channels) {
      expect(ch.signatureValid).toBe(true);
      expect(ch.publicKeyUrl).toContain("release-pubkey.json");
    }
  });

  it("signatureValid is false when signature does not match (wrong key)", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);

    const kp1 = await generateKeyPair();
    const kp2 = await generateKeyPair();
    const pubKeyHex2 = toHex(kp2.publicKey);

    const identity = {
      distTreeHash: "sha256:abc123",
      releaseId: "r000005",
      missionId: "m000076",
      buildTimestamp: "2026-08-23T12:45:06Z",
    };
    const idPath = join(tmpDir, "build-identity.json");
    writeFileSync(idPath, JSON.stringify(identity));
    await signBuildIdentity({
      buildIdentityPath: idPath,
      privateKeyBytes: kp1.privateKey,
    });
    const signedIdentity = JSON.parse(readFileSync(idPath, "utf8"));

    const pubKeyJson = JSON.stringify({
      keyId: "test-key-id",
      publicKeyHex: pubKeyHex2,
      algorithm: "Ed25519",
      createdAt: "2026-08-23T12:00:00.000Z",
    });

    vi.spyOn(globalThis, "fetch").mockImplementation((url: string | URL | Request) => {
      const urlStr = typeof url === "string" ? url : url.toString();
      if (urlStr.includes("release-pubkey.json")) {
        return Promise.resolve(new Response(pubKeyJson, { status: 200 }));
      }
      return Promise.resolve(new Response(JSON.stringify(signedIdentity), { status: 200 }));
    });

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "verify-signature": true }),
      makeContext("/tmp"),
    );

    for (const ch of result.data!.channels) {
      expect(ch.signatureValid).toBe(false);
    }
  });

  it("signatureValid is null when release-pubkey.json is not found (404)", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);

    vi.spyOn(globalThis, "fetch").mockImplementation((url: string | URL | Request) => {
      const urlStr = typeof url === "string" ? url : url.toString();
      if (urlStr.includes("release-pubkey.json")) {
        return Promise.resolve(new Response("Not Found", { status: 404 }));
      }
      return Promise.resolve(new Response(mockBuildIdentity("sha256:abc123"), { status: 200 }));
    });

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "verify-signature": true }),
      makeContext("/tmp"),
    );

    for (const ch of result.data!.channels) {
      expect(ch.signatureValid).toBeNull();
    }
  });

  it("signatureValid is null when build-identity.json has no signature field", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);

    const pubKeyJson = JSON.stringify({
      keyId: "test-key-id",
      publicKeyHex: toHex(keyPair.publicKey),
      algorithm: "Ed25519",
      createdAt: "2026-08-23T12:00:00.000Z",
    });

    vi.spyOn(globalThis, "fetch").mockImplementation((url: string | URL | Request) => {
      const urlStr = typeof url === "string" ? url : url.toString();
      if (urlStr.includes("release-pubkey.json")) {
        return Promise.resolve(new Response(pubKeyJson, { status: 200 }));
      }
      // Unsigned build-identity.json
      return Promise.resolve(new Response(mockBuildIdentity("sha256:abc123"), { status: 200 }));
    });

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "verify-signature": true }),
      makeContext("/tmp"),
    );

    for (const ch of result.data!.channels) {
      expect(ch.signatureValid).toBe(false);
    }
  });
});

src/tests-handoff/release-0596-artifact-.source:
/*
<MODULE_CONTRACT>
<purpose>RFC-0596: tests for storeArtifactCore extraction, automatic artifact storage in release.ready, and release.validate artifact check.</purpose>
<keywords>RFC-0596, storeArtifactCore, release.ready, artifact storage, release.validate, test</keywords>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>RFC-0596: add unit tests for storeArtifactCore (lock-free, idempotent, systemId), release.ready artifact-before-transition, and release.validate ready-artifact check.</item>
</CHANGE_SUMMARY>
*/

import { test, expect, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  rmSync,
  mkdirSync,
  writeFileSync,
  existsSync,
  readdirSync,
  readFileSync,
} from "node:fs";
import { join, resolve } from "node:path";
import { stringify as stringifyYaml, parse as parseYaml } from "yaml";
import { storeArtifactCore } from "../artifact-store/artifact-store-commands.ts";
import { runReleaseReady, runReleaseValidate } from "../release/release-commands.ts";
import type { KernelRuntimeContext, KernelCommandInput } from "@warpgogol/werkstatt-engine/kernel";
import { expectData } from "./helpers/kernel-result-helpers.ts";
import { tmpdir } from "node:os";

function makeContext(workspaceRoot: string): KernelRuntimeContext {
  return {
    workspaceRoot,
    logger: {
      info: () => {},
      success: () => {},
      warn: () => {},
      error: () => {},
      debug: () => {},
    },
    flags: {},
    env: {},
  } as unknown as KernelRuntimeContext;
}

function makeInput(flags: Record<string, string>): KernelCommandInput {
  return { flags, argv: [] };
}

function writeReleaseManifest(
  workspaceRoot: string,
  releaseId: string,
  fields: Record<string, unknown>,
): void {
  const releaseDir = join(workspaceRoot, "releases", releaseId);
  mkdirSync(releaseDir, { recursive: true });
  const defaults: Record<string, unknown> = {
    schemaVersion: "1.0.0",
    releaseId,
    systemId: "test-sys",
    missionId: "test-mission-m000001",
    semver: "0.1.0",
    platformVersion: "1.0.0",
    createdAt: "2026-01-01T00:00:00.000Z",
    readyAt: null,
    state: "prepared",
    commitSha: "0000000",
    platformSemanticHash: "sha256:semantic",
    siteContentHash: "sha256:content",
    distTreeHash: "sha256:abc123def456",
    distArtifactHash: null,
    artifact: null,
    behaviorSnapshotHash: "sha256:behavior",
    readableSnapshotHash: "sha256:readable",
    qualityReportHash: null,
    snapshotDiffVerdict: "pass",
    migratorVerdict: "pass",
    versionCompareVerdict: "in-sync",
    bootSmokeVerdict: "pass",
  };
  const merged = { ...defaults, ...fields };
  writeFileSync(join(releaseDir, "release.yaml"), stringifyYaml(merged));
}

function readReleaseManifestFile(
  workspaceRoot: string,
  releaseId: string,
): Record<string, unknown> {
  const content = readFileSync(join(workspaceRoot, "releases", releaseId, "release.yaml"), "utf8");
  return parseYaml(content) as Record<string, unknown>;
}

function createDistDir(workspaceRoot: string, releaseId: string): string {
  const distDir = join(workspaceRoot, "releases", releaseId, "dist");
  mkdirSync(distDir, { recursive: true });
  writeFileSync(join(distDir, "index.html"), "<html><body>Hello</body></html>");
  return distDir;
}

function createRegistry(workspaceRoot: string, systemId: string, cachePath: string): void {
  const registryDir = join(workspaceRoot, "systems");
  mkdirSync(registryDir, { recursive: true });
  const registryContent = `schemaVersion: "1.0.0"
systems:
  - id: ${systemId}
    cosmicStar: Acamar
    mirrors:
      - path: ${cachePath}
        storageType: non-bare
    pinnedPlatform: 1.0.0
    currentMission: null
    lastRelease: null
    status: active
    registeredAt: 2026-01-01T00:00:00.000Z
    notes: ""
`;
  writeFileSync(join(registryDir, "registry.yaml"), registryContent);
}

let tmpDir: string;

beforeEach(() => {
  tmpDir = mkdtempSync(join(tmpdir(), "tmp-release-0596-"));
});

afterEach(() => {
  rmSync(tmpDir, { recursive: true, force: true });
  // resolveCacheClonePath uses ../systems-cache relative to workspaceRoot,
  // which escapes tmpDir. Clean up to prevent stale system-state.yaml across runs.
  rmSync(resolve(tmpDir, "..", "systems-cache"), { recursive: true, force: true });
});

// --- storeArtifactCore tests ---

test("storeArtifactCore stores artifact manifest and returns correct fields", async () => {
  const releaseId = "test-sys-r000001";
  const distDir = join(tmpDir, "releases", releaseId, "dist");
  mkdirSync(distDir, { recursive: true });
  writeFileSync(join(distDir, "index.html"), "<html></html>");

  const result = await storeArtifactCore(tmpDir, releaseId, distDir, "test-sys");

  expect(result.distArtifactHash).toMatch(/^sha256:/);
  expect(result.uri).toMatch(/^local:\/\//);
  expect(result.distTreeHash).toMatch(/^sha256:/);
  expect(result.byteSize).toBeGreaterThan(0);
  expect(result.fileCount).toBe(1);
  expect(result.createdAt).toBeTruthy();

  // Verify manifest file exists on disk
  const manifestUri = result.uri.replace("local://", "");
  expect(existsSync(manifestUri)).toBe(true);
  const manifest = JSON.parse(readFileSync(manifestUri, "utf8"));
  expect(manifest.releaseId).toBe(releaseId);
  expect(manifest.systemId).toBe("test-sys");
  expect(manifest.distArtifactHash).toBe(result.distArtifactHash);
});

test("storeArtifactCore does not create lock files", async () => {
  const releaseId = "test-sys-r000002";
  const distDir = join(tmpDir, "releases", releaseId, "dist");
  mkdirSync(distDir, { recursive: true });
  writeFileSync(join(distDir, "index.html"), "<html></html>");

  await storeArtifactCore(tmpDir, releaseId, distDir, "test-sys");

  // Check no lock files were created
  const lockDir = join(tmpDir, ".werkstatt", "locks");
  if (existsSync(lockDir)) {
    const lockFiles = readdirSync(lockDir);
    expect(lockFiles).toHaveLength(0);
  }
});

test("storeArtifactCore uses provided systemId, not releaseId.split", async () => {
  const releaseId = "my-system-r000003";
  const distDir = join(tmpDir, "releases", releaseId, "dist");
  mkdirSync(distDir, { recursive: true });
  writeFileSync(join(distDir, "index.html"), "<html></html>");

  // Pass a systemId that differs from what releaseId.split("-r")[0] would produce
  const result = await storeArtifactCore(tmpDir, releaseId, distDir, "custom-sys-id");

  const manifestUri = result.uri.replace("local://", "");
  const manifest = JSON.parse(readFileSync(manifestUri, "utf8"));
  expect(manifest.systemId).toBe("custom-sys-id");
  expect(manifest.systemId).not.toBe("my-system");
});

test("storeArtifactCore is idempotent — re-running overwrites manifest", async () => {
  const releaseId = "test-sys-r000004";
  const distDir = join(tmpDir, "releases", releaseId, "dist");
  mkdirSync(distDir, { recursive: true });
  writeFileSync(join(distDir, "index.html"), "<html>v1</html>");

  const result1 = await storeArtifactCore(tmpDir, releaseId, distDir, "test-sys");

  // Run again with same content — should overwrite, not duplicate
  const result2 = await storeArtifactCore(tmpDir, releaseId, distDir, "test-sys");

  expect(result2.distArtifactHash).toBe(result1.distArtifactHash);
  expect(result2.uri).toBe(result1.uri);
});

// --- release.ready tests ---

test("release.ready stores artifact before state transition", async () => {
  const releaseId = "test-sys-r000010";
  const systemId = "test-sys";
  const cachePath = join(tmpDir, "cache", systemId);
  mkdirSync(cachePath, { recursive: true });

  createRegistry(tmpDir, systemId, cachePath);
  createDistDir(tmpDir, releaseId);

  writeReleaseManifest(tmpDir, releaseId, {
    releaseId,
    systemId,
    state: "prepared",
    distTreeHash: "sha256:abc123def456",
  });

  const result = await runReleaseReady(makeInput({ release: releaseId }), makeContext(tmpDir));

  expect(expectData(result).state).toBe("ready");
  expect(expectData(result).artifactUri).not.toBeNull();
  expect(expectData(result).distArtifactHash).not.toBeNull();
  expect(expectData(result).distArtifactHash).toMatch(/^sha256:/);

  // Verify release.yaml has artifact and distArtifactHash set AND state: ready
  const manifest = readReleaseManifestFile(tmpDir, releaseId);
  expect(manifest.state).toBe("ready");
  expect(manifest.artifact).not.toBeNull();
  expect(manifest.distArtifactHash).not.toBeNull();
  const artifact = manifest.artifact as Record<string, unknown>;
  expect(artifact.uri).toMatch(/^local:\/\//);
});

test("release.ready output includes distArtifactHash field", async () => {
  const releaseId = "test-sys-r000011";
  const systemId = "test-sys";
  const cachePath = join(tmpDir, "cache", systemId);
  mkdirSync(cachePath, { recursive: true });

  createRegistry(tmpDir, systemId, cachePath);
  createDistDir(tmpDir, releaseId);

  writeReleaseManifest(tmpDir, releaseId, {
    releaseId,
    systemId,
    state: "prepared",
    distTreeHash: "sha256:abc123def456",
  });

  const result = await runReleaseReady(makeInput({ release: releaseId }), makeContext(tmpDir));

  expect(result.data).toHaveProperty("distArtifactHash");
  expect(expectData(result).distArtifactHash).not.toBeNull();
  expect(expectData(result).distArtifactHash).toMatch(/^sha256:/);
});

test("release.ready fails on missing dist — state remains prepared", async () => {
  const releaseId = "test-sys-r000012";
  const systemId = "test-sys";

  writeReleaseManifest(tmpDir, releaseId, {
    releaseId,
    systemId,
    state: "prepared",
    distTreeHash: "sha256:abc123def456",
  });

  await expect(
    runReleaseReady(makeInput({ release: releaseId }), makeContext(tmpDir)),
  ).rejects.toThrow(/no dist\/ directory/);

  // Verify state remains prepared
  const manifest = readReleaseManifestFile(tmpDir, releaseId);
  expect(manifest.state).toBe("prepared");
});

// --- release.validate tests ---

test("release.validate flags ready release without artifact", async () => {
  const releaseId = "test-sys-r000020";

  writeReleaseManifest(tmpDir, releaseId, {
    releaseId,
    systemId: "test-sys",
    state: "ready",
    artifact: null,
  });

  const result = await runReleaseValidate(makeInput({ release: releaseId }), makeContext(tmpDir));

  expect(expectData(result).state).toBe("ready");
  expect(expectData(result).artifactPresent).toBe(false);
});

test("release.validate passes ready release with artifact", async () => {
  const releaseId = "test-sys-r000021";

  writeReleaseManifest(tmpDir, releaseId, {
    releaseId,
    systemId: "test-sys",
    state: "ready",
    artifact: {
      uri: "local:///some/path/manifest.json",
      provider: "local",
      distArtifactHash: "sha256:abc",
      distTreeHash: "sha256:def",
      siteContentHash: "sha256:ghi",
      byteSize: 100,
      fileCount: 1,
    },
  });

  const result = await runReleaseValidate(makeInput({ release: releaseId }), makeContext(tmpDir));

  expect(expectData(result).state).toBe("ready");
  expect(expectData(result).artifactPresent).toBe(true);
});

src/leitstand/tests/leitstand-verify.tes.source:
/*
<MODULE_CONTRACT>
  <purpose>RFC-0930: unit tests for leitstand.verify command — fetches build-identity.json from live channels, compares distTreeHash cross-channel, optionally compares against local system-state.yaml.</purpose>
</MODULE_CONTRACT>
<CHANGE_SUMMARY>
  <item>RFC-0930: initial tests for leitstand.verify command covering all-match success, hash drift, unreachable channel, local mismatch, single-channel filter, access-protected channel, 404, no deployment config, --no-compare-local, and fetch timeout.</item>
</CHANGE_SUMMARY>
*/

import { describe, expect, it, vi, afterEach } from "vitest";

vi.mock("../../sternsystem/registry-io.ts", () => ({
  readSystemConfigSmart: vi.fn(),
  readSystemStateSmart: vi.fn(),
  resolveCacheClonePath: vi.fn(),
}));

const { runLeitstandVerify } = await import("../leitstand-commands.ts");
const { readSystemConfigSmart, readSystemStateSmart } =
  await import("../../sternsystem/registry-io.ts");

function makeInput(flags: Record<string, unknown>) {
  return { flags, args: [] } as unknown as Parameters<typeof runLeitstandVerify>[0];
}

function makeContext(workspaceRoot: string) {
  return { workspaceRoot, dryRun: false, site: undefined } as unknown as Parameters<
    typeof runLeitstandVerify
  >[1];
}

const defaultConfig = {
  schemaVersion: "1.0.0",
  id: "test-site",
  deployment: {
    adapter: "cloudflare-workers" as const,
    channels: {
      dev: { workerName: "dev-test", url: "https://dev.test.com" },
      alt: { workerName: "alt-test", url: "https://alt.test.com" },
      main: { workerName: "test", url: "https://test.com" },
    },
  },
};

const defaultState = {
  schemaVersion: "1.0.0",
  systemId: "test-site",
  currentMission: null,
  lastRelease: null,
  lastPropagated: {
    dev: {
      releaseId: "r000005",
      at: "2026-08-23T12:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-1",
      leaseExpiresAt: null,
    },
    alt: {
      releaseId: "r000005",
      at: "2026-08-23T13:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-2",
      leaseExpiresAt: null,
    },
    main: {
      releaseId: "r000005",
      at: "2026-08-23T14:00:00.000Z",
      healthy: true,
      state: "succeeded" as const,
      operationId: "op-3",
      leaseExpiresAt: null,
    },
  },
  accessPin: null as string | null,
};

function mockBuildIdentity(distTreeHash: string, releaseId = "r000005") {
  return JSON.stringify({
    distTreeHash,
    releaseId,
    missionId: "m000076",
    buildTimestamp: "2026-08-23T12:45:06Z",
  });
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe("RFC-0930: leitstand.verify", () => {
  it("all-match success: all channels reachable, same hash, match local → exitCode 0", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc123"), { status: 200 })),
    );

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(0);
    expect(result.data!.crossChannel.allReachable).toBe(true);
    expect(result.data!.crossChannel.allSameHash).toBe(true);
    expect(result.data!.crossChannel.commonHash).toBe("sha256:abc123");
    expect(result.data!.channels).toHaveLength(3);
    for (const ch of result.data!.channels) {
      expect(ch.matchesLocal).toBe(true);
      expect(ch.reachable).toBe(true);
    }
  });

  it("hash drift: channels return different distTreeHash → exitCode 1", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    const hashes = ["sha256:aaa", "sha256:bbb", "sha256:ccc"];
    let callIndex = 0;
    vi.spyOn(globalThis, "fetch").mockImplementation(() => {
      const hash = hashes[callIndex++ % hashes.length];
      return Promise.resolve(new Response(mockBuildIdentity(hash), { status: 200 }));
    });

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(1);
    expect(result.data!.crossChannel.allSameHash).toBe(false);
    expect(result.data!.crossChannel.commonHash).toBeNull();
  });

  it("unreachable channel: main returns HTTP 500 → exitCode 1", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation((url: string | URL | Request) => {
      const urlStr = typeof url === "string" ? url : url.toString();
      if (urlStr.includes("test.com/.well-known")) {
        return Promise.resolve(new Response("Internal Server Error", { status: 500 }));
      }
      return Promise.resolve(new Response(mockBuildIdentity("sha256:abc"), { status: 200 }));
    });

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(1);
    expect(result.data!.crossChannel.allReachable).toBe(false);
    const mainCh = result.data!.channels.find((c) => c.channel === "main");
    expect(mainCh?.reachable).toBe(false);
    expect(mainCh?.httpStatus).toBe(500);
  });

  it("local mismatch: live releaseId differs from system-state.yaml → exitCode 1", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc", "r000099"), { status: 200 })),
    );

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(1);
    for (const ch of result.data!.channels) {
      expect(ch.matchesLocal).toBe(false);
    }
  });

  it("single-channel filter: --channel dev → only dev in output", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc"), { status: 200 })),
    );

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", channel: "dev" }),
      makeContext("/tmp"),
    );

    expect(result.data!.channels).toHaveLength(1);
    expect(result.data!.channels[0].channel).toBe("dev");
  });

  it("access-protected channel: auth header sent when accessPin is set", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce({
      ...defaultState,
      accessPin: "1234",
    } as never);
    const fetchSpy = vi
      .spyOn(globalThis, "fetch")
      .mockImplementation(() =>
        Promise.resolve(new Response(mockBuildIdentity("sha256:abc"), { status: 200 })),
      );

    await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(fetchSpy).toHaveBeenCalled();
    const callArgs = fetchSpy.mock.calls[0];
    const options = callArgs?.[1] as RequestInit | undefined;
    expect(options?.headers).toHaveProperty("Authorization");
    const authHeader = (options?.headers as Record<string, string>)?.Authorization;
    expect(authHeader).toMatch(/^Basic /);
    expect(atob(authHeader!.replace("Basic ", ""))).toBe("warp:1234");
  });

  it("build-identity 404: channel returns 404 → buildIdentity null, error set", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response("Not Found", { status: 404 })),
    );

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(1);
    for (const ch of result.data!.channels) {
      expect(ch.buildIdentity).toBeNull();
      expect(ch.error).toBe("build-identity.json not found");
    }
  });

  it("no deployment config: returns empty channels, exitCode 0", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce({
      schemaVersion: "1.0.0",
      id: "test-site",
      deployment: undefined,
    } as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);

    const result = await runLeitstandVerify(makeInput({ site: "test-site" }), makeContext("/tmp"));

    expect(result.exitCode).toBe(0);
    expect(result.data!.channels).toHaveLength(0);
    expect(result.data!.crossChannel.allReachable).toBe(true);
    expect(result.data!.crossChannel.allSameHash).toBe(true);
    expect(result.summary).toContain("no deployment config");
  });

  it("--no-compare-local: matchesLocal is null for all channels", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc"), { status: 200 })),
    );

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "compare-local": false }),
      makeContext("/tmp"),
    );

    for (const ch of result.data!.channels) {
      expect(ch.matchesLocal).toBeNull();
    }
  });

  it("fetch timeout: AbortError → reachable false, error mentions timeout", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation((_url, init) => {
      return new Promise((_resolve, reject) => {
        const signal = init?.signal;
        if (signal) {
          signal.addEventListener("abort", () => {
            const err = new Error("Aborted");
            err.name = "AbortError";
            reject(err);
          });
        }
      });
    });

    const result = await runLeitstandVerify(
      makeInput({ site: "test-site", "timeout-ms": "50" }),
      makeContext("/tmp"),
    );

    expect(result.exitCode).toBe(1);
    for (const ch of result.data!.channels) {
      expect(ch.reachable).toBe(false);
      expect(ch.error).toContain("timeout");
    }
  });

  it("throws if --site is missing", async () => {
    await expect(runLeitstandVerify(makeInput({}), makeContext("/tmp"))).rejects.toThrow(
      "--site is required",
    );
  });

  it("--system alias works as --site", async () => {
    vi.mocked(readSystemConfigSmart).mockResolvedValueOnce(defaultConfig as never);
    vi.mocked(readSystemStateSmart).mockResolvedValueOnce(defaultState as never);
    vi.spyOn(globalThis, "fetch").mockImplementation(() =>
      Promise.resolve(new Response(mockBuildIdentity("sha256:abc"), { status: 200 })),
    );

    const result = await runLeitstandVerify(
      makeInput({ system: "test-site" }),
      makeContext("/tmp"),
    );

    expect(result.data!.systemId).toBe("test-site");
  });
});

